<template>
  <div id="option-root">
    <!-- Header -->
    <header class="app-header">
      <div class="header-brand">
        <img class="header-logo" :src="logoImg" />
        <div class="header-text">
          <div class="header-title">IG Comment Exporter</div>
          <div class="header-subtitle">Export Instagram comments to CSV / Excel</div>
        </div>
      </div>
      <div class="header-actions">
        <button 
          v-if="isLoggedIn && !isProUser" 
          type="button" 
          class="btn-pro" 
          @click="showPricingDialog = true"
        >
          <svg width="14" height="14" viewBox="0 0 24 24" fill="currentColor" style="margin-right: 4px;">
            <path d="M12 2L15.09 8.26L22 9.27L17 14.14L18.18 21.02L12 17.77L5.82 21.02L7 14.14L2 9.27L8.91 8.26L12 2Z"/>
          </svg>
          Upgrade to Pro
        </button>
        <div v-if="isLoggedIn" class="user-badge">
          <span class="user-avatar">{{ displayUserName.charAt(0).toUpperCase() }}</span>
          <div class="user-text">
            <span class="user-email">{{ displayMaskedUser }}</span>
            <span v-if="isProUser" class="user-plan">Pro</span>
          </div>
          <span class="user-badge-caret">▾</span>
          <div class="user-menu">
            <button type="button" class="user-menu-item" @click="onLogout">Sign out</button>
          </div>
        </div>
        <button v-else type="button" class="btn-outline btn-sm" @click="showAccountDialog = true">
          Sign in
        </button>
      </div>
    </header>

    <!-- Limit Notice Banner -->
    <div v-if="!isProUser" class="limit-banner">
      <div class="limit-banner-inner">
        <div class="limit-banner-icon">
          <svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor">
            <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm1 15h-2v-6h2v6zm0-8h-2V7h2v2z"/>
          </svg>
        </div>
        <div class="limit-banner-text">
          The maximum number of free account to export is <strong>1e6</strong>,
          you can upgrade to Pro for <strong>unlimited</strong> exports.
          <a
            href="javascript:void(0)"
            class="limit-banner-link"
            @click.prevent="handleUpgradeClick"
          >UPGRADE NOW!! ›</a>
        </div>
      </div>
    </div>
    
    <!-- Pro User Banner -->
    <div v-else class="pro-banner">
      <div class="pro-banner-inner">
        <div class="pro-banner-icon">
          <svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor">
            <path d="M12 2L15.09 8.26L22 9.27L17 14.14L18.18 21.02L12 17.77L5.82 21.02L7 14.14L2 9.27L8.91 8.26L12 2Z"/>
          </svg>
        </div>
        <div class="pro-banner-text">
          🎉 <strong>Pro Member</strong> - Enjoy unlimited exports with no restrictions!
        </div>
      </div>
    </div>

    <!-- Main -->
    <div class="app-body">
      <!-- Left: Export Settings -->
      <div class="panel panel-left">
        <div class="panel-header">
          <div class="panel-title">Export Settings</div>
          <div class="panel-desc">Configure the Instagram post and fetch options below.</div>
        </div>

        <div class="form-section">
          <label class="form-label" for="postUrlInput">
            Instagram Post URL
          </label>
          <input
            id="postUrlInput"
            class="form-input"
            type="text"
            v-model="postUrl"
            placeholder="https://www.instagram.com/p/CDrcwykscvS/ or /reels/DUomONwANAz/"
            @blur="onBlurInput('postUrl')"
          />
          <div class="form-hint">Paste any Instagram post, Reel, or IGTV URL to start exporting comments.</div>
          <div class="form-note">
            <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="flex-shrink: 0; margin-top: 2px;">
              <circle cx="12" cy="12" r="10"/><line x1="12" y1="16" x2="12" y2="12"/><line x1="12" y1="8" x2="12.01" y2="8"/>
            </svg>
            <span>Note: Instagram API may limit exports. Progress auto-saves every 10 pages and on browser close - you can resume anytime.</span>
          </div>
        </div>

        <div class="form-section">
          <div class="form-label-row">
            <label class="form-label" for="intervalSecInputRange">
              Request Delay
            </label>
            <span :class="['delay-badge', intervalSec < 5 ? 'delay-badge-warn' : 'delay-badge-safe']">
              {{ intervalSec }}s · {{ intervalSec < 5 ? 'High risk' : 'Safe' }}
            </span>
          </div>
          <div class="range-row">
            <input
              type="range"
              id="intervalSecInputRange"
              class="range-input"
              min="0.5"
              max="100"
              v-model="intervalSec"
            />
            <input
              class="number-input"
              type="number"
              v-model="intervalSec"
              max="100"
              min="0.5"
              step="0.5"
              @blur="onBlurInput('intervalSec')"
            />
          </div>
          <transition name="fade">
            <p v-if="intervalSec < 5" class="risk-msg">
              ⚠ {{ riskyMessage }}
            </p>
          </transition>
          <div class="form-hint">A longer delay reduces risk to your Instagram account. We recommend ≥ 5s.</div>
        </div>

        <div class="action-row">
          <!-- 开始按钮：无保存进度且已停止时 -->
          <button
            v-if="!hasSavedProgress && (runningStat === RUN_STAT_STOPPED || runningStat === RUN_STAT_FINISHED)"
            :class="['btn', canStartParsing ? 'btn-primary' : 'btn-disabled']"
            :disabled="!canStartParsing"
            @click="fetchLead()"
          >
            <svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor" style="margin-right:6px"><path d="M8 5v14l11-7z"/></svg>
            Start parsing
          </button>
          
          <!-- 继续按钮：有保存进度且已停止时 -->
          <button
            v-if="hasSavedProgress && runningStat === RUN_STAT_STOPPED"
            :class="['btn', 'btn-success']"
            @click="resumeFetch()"
          >
            <svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor" style="margin-right:6px"><path d="M8 5v14l11-7z"/></svg>
            Resume parsing
          </button>
          
          <!-- 暂停按钮：运行中或冷却中时 -->
          <button
            v-if="canPauseParsing"
            :class="['btn', 'btn-warning']"
            @click="pauseLead()"
          >
            <svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor" style="margin-right:6px"><path d="M6 4h4v16H6zM14 4h4v16h-4z"/></svg>
            Pause parsing
          </button>
          
          <!-- 停止并重置按钮：运行中或冷却中时，或有保存进度时 -->
          <button
            v-if="runningStat === RUN_STAT_RUNNING || runningStat === RUN_STAT_COOLDOWN || (hasSavedProgress && runningStat === RUN_STAT_STOPPED)"
            :class="['btn', hasSavedProgress && runningStat === RUN_STAT_STOPPED ? 'btn-outline' : 'btn-danger']"
            @click="stopLead()"
          >
            <svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor" style="margin-right:6px"><path d="M6 6h12v12H6z"/></svg>
            {{ runningStat === RUN_STAT_STOPPED ? 'Clear progress' : 'Stop & Reset' }}
          </button>
        </div>
        <div v-if="hasSavedProgress && runningStat === RUN_STAT_STOPPED" class="saved-progress-hint">
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#10b981" stroke-width="2" style="flex-shrink: 0;">
            <path d="M9 11l3 3L22 4"/><path d="M21 12v7a2 2 0 01-2 2H5a2 2 0 01-2-2V5a2 2 0 012-2h11"/>
          </svg>
          <span>Progress saved: {{ savedProgressComments }} comments from previous session. Click Resume to continue.</span>
        </div>
      </div>

      <!-- Right: Progress + Export -->
      <div class="panel-right-col">
        <!-- Progress -->
        <div class="panel panel-progress">
          <div class="panel-header">
            <div class="panel-title">Progress</div>
          </div>

          <div class="stat-list">
            <div class="stat-item">
              <span class="stat-label">Status</span>
              <span v-if="runningStat == 0 && hasSavedProgress" class="stat-tag stat-tag-orange">Paused</span>
              <span v-else-if="runningStat == 0" class="stat-tag stat-tag-neutral">Stopped</span>
              <span v-else-if="runningStat == 1" class="stat-tag stat-tag-blue">In progress</span>
              <span v-else-if="runningStat == 2" class="stat-tag stat-tag-yellow">Cooldown {{ coolDownSec }}s</span>
              <span v-else class="stat-tag stat-tag-green">Finished</span>
            </div>
            <div class="stat-item" v-if="errorMessage">
              <span class="stat-label">Error</span>
              <span class="stat-value stat-error">{{ errorMessage }}</span>
            </div>
            <div class="stat-item">
              <span class="stat-label">Total comments</span>
              <span class="stat-value stat-num">{{ totalComments }}</span>
            </div>
            <div class="stat-item">
              <span class="stat-label">Found comments</span>
              <span class="stat-value stat-num stat-highlight">{{ foundComments }}</span>
            </div>
          </div>

          <!-- Progress bar -->
          <div class="progress-bar-wrap" v-if="totalComments > 0">
            <div
              class="progress-bar-fill"
              :style="{ width: progressPercent + '%' }"
            ></div>
          </div>
          <div v-if="runningStat === RUN_STAT_RUNNING || runningStat === RUN_STAT_COOLDOWN" class="auto-save-hint">
            <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" class="auto-save-icon">
              <path d="M19 21H5a2 2 0 01-2-2V5a2 2 0 012-2h11l5 5v11a2 2 0 01-2 2z"/><polyline points="17 21 17 13 7 13 7 21"/><polyline points="7 3 7 8 15 8"/>
            </svg>
            <span>Auto-saving every 10 pages</span>
          </div>
          <div v-if="totalComments > 500 && (runningStat === RUN_STAT_RUNNING || runningStat === RUN_STAT_COOLDOWN)" class="api-limit-notice">
            <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
              <circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/>
            </svg>
            <span>Note: Instagram API may not allow fetching all {{ totalComments }} comments</span>
          </div>
        </div>

        <!-- Export Buttons -->
        <div class="panel panel-export">
          <div class="panel-header">
            <div class="panel-title">Export Data</div>
            <div class="panel-desc">{{ foundComments > 0 ? foundComments + ' comments ready' : 'No data yet' }}</div>
          </div>
          <div class="export-btn-group">
            <button
              :class="['btn', 'btn-export', foundComments > 0 ? 'btn-export-csv' : 'btn-disabled']"
              :disabled="foundComments <= 0"
              @click="exportCSV()"
            >
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="margin-right:6px"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/></svg>
              Save to CSV
            </button>
            <button
              :class="['btn', 'btn-export', foundComments > 0 ? 'btn-export-excel' : 'btn-disabled']"
              :disabled="foundComments <= 0"
              @click="exportExcel()"
            >
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="margin-right:6px"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/></svg>
              Save to Excel
            </button>
          </div>
        </div>

        <!-- Footer links -->
        <div class="app-footer">
          <a href="mailto:" class="footer-link" @click="clickContactUs">
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="margin-right: 4px; vertical-align: middle;">
              <path d="M4 4h16c1.1 0 2 .9 2 2v12c0 1.1-.9 2-2 2H4c-1.1 0-2-.9-2-2V6c0-1.1.9-2 2-2z"/>
              <polyline points="22,6 12,13 2,6"/>
            </svg>
            Contact Us ()
          </a>
        </div>
      </div>
    </div>

    <!-- Comment List Section -->
    <div class="comment-section" v-if="commentList.length > 0 || runningStat === 1 || runningStat === 2">
      <!-- Progress Banner -->
      <div class="progress-banner" v-if="runningStat === 1 || runningStat === 2">
        <div class="progress-banner-text">
          <svg v-if="runningStat === 1" class="spin-icon" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5">
            <path d="M12 2v4M12 18v4M4.93 4.93l2.83 2.83M16.24 16.24l2.83 2.83M2 12h4M18 12h4M4.93 19.07l2.83-2.83M16.24 7.76l2.83-2.83"/>
          </svg>
          <svg v-else width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#d97706" stroke-width="2.5">
            <circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/>
          </svg>
          <span v-if="runningStat === 1">
            Exporting <strong>{{ foundComments }}</strong> / <strong>{{ totalComments || '...' }}</strong> comments, please wait a moment...
          </span>
          <span v-else>
            Cooling down ({{ coolDownSec }}s), will resume shortly...
          </span>
        </div>
        <div class="progress-banner-actions">
          <button
            class="btn-banner-stop"
            @click="stopLead()"
          >
            <svg width="12" height="12" viewBox="0 0 24 24" fill="currentColor"><path d="M6 6h12v12H6z"/></svg>
            Stop
          </button>
          <button
            v-if="foundComments > 0"
            class="btn-banner-download"
            @click="exportCSV()"
          >
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg>
            Download {{ foundComments }} comments
          </button>
        </div>
      </div>

      <!-- Progress Bar + Limit notice (unified block) -->
      <div
        class="list-status-card"
        v-if="(totalComments > 0 || limitReached) || (runningStat === 0 && foundComments >= 1e6)"
      >
        <div class="list-progress-wrap" v-if="totalComments > 0 || limitReached">
          <div
            class="list-progress-fill"
            :style="{ width: progressPercent + '%' }"
          ></div>
          <span class="list-progress-pct">{{ progressPercent }}%</span>
        </div>

        <!-- Limit reached notice -->
        <div class="list-limit-bar" v-if="runningStat === 0 && foundComments >= 1e6">
          <div class="list-limit-left">
            <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="flex-shrink:0">
              <circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/>
            </svg>
            <span>
              Free account limit reached (<strong>{{ foundComments }}</strong> / 100).
              Upgrade to Pro for <strong>unlimited</strong> exports.
            </span>
          </div>
          <a
            href="javascript:void(0)"
            class="list-limit-link"
            @click.prevent="handleUpgradeClick"
          >Upgrade Now →</a>
        </div>
      </div>

      <div class="availability-notice" v-if="availabilityNotice">
        <div class="availability-notice-icon">
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
            <circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/>
          </svg>
        </div>
        <div class="availability-notice-text">
          <strong>Instagram data delay</strong>
          <p>{{ availabilityNotice }}</p>
        </div>
      </div>

      <!-- API Limit Warning (when data is incomplete) -->
      <div class="api-limit-warning" v-if="runningStat === 3 && totalComments - commentList.length > 100">
        <div class="api-limit-icon">
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
            <circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/>
          </svg>
        </div>
        <div class="api-limit-text">
          <strong>Instagram API Limitation</strong>
          <p>Only {{ Math.round((commentList.length / totalComments) * 100) }}% of comments ({{ commentList.length }}/{{ totalComments }}) could be fetched due to Instagram's API restrictions. This is a platform limitation, not a tool issue.</p>
        </div>
      </div>

      <!-- Export actions when finished -->
      <div class="list-export-bar" v-if="(runningStat === 0 || runningStat === 3) && commentList.length > 0">
        <div class="list-export-info">
          <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="#16a34a" stroke-width="2.5"><polyline points="20 6 9 17 4 12"/></svg>
          <span>{{ commentList.length }} comments collected{{ totalComments - commentList.length > 100 ? ` (${totalComments} total shown)` : '' }}</span>
        </div>
        <div class="list-export-btns">
          <button class="btn-export-sm btn-export-sm-csv" @click="exportCSV()">
            <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/></svg>
            Save CSV
          </button>
          <button class="btn-export-sm btn-export-sm-excel" @click="exportExcel()">
            <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/></svg>
            Save Excel
          </button>
        </div>
      </div>

      <!-- Comment Table -->
      <div class="comment-table-wrap">
        <table class="comment-table">
          <thead>
            <tr>
              <th class="col-no">NO.</th>
              <th class="col-avatar">Avatar</th>
              <th class="col-username">Username</th>
              <th class="col-text">Comment</th>
              <th class="col-date">Date</th>
            </tr>
          </thead>
          <tbody>
            <tr v-for="(item, index) in commentList" :key="(item.commentId || item.id) + index">
              <td class="col-no">{{ index + 1 }}</td>
              <td class="col-avatar">
                <div class="avatar-wrap">
                  <div class="avatar-fallback">{{ (item.userName || '?').charAt(0).toUpperCase() }}</div>
                  <img
                    v-if="item.avatarUrl"
                    :src="proxyImg(item.avatarUrl)"
                    class="avatar-img"
                    :alt="item.userName"
                    @error="e => e.target.style.display='none'"
                  />
                </div>
              </td>
              <td class="col-username">
                <a :href="item.profileUrl" target="_blank" class="username-link">{{ item.userName }}</a>
              </td>
              <td class="col-text">{{ item.text }}</td>
              <td class="col-date">{{ item.date }}</td>
            </tr>
          </tbody>
        </table>
      </div>
    </div>

    <!-- Dialogs -->
    <need-login-dialog
      v-if="showNeedLogin"
      @onClickClose="showNeedLogin = false"
    />
    <bonus-verify-dialog
      v-if="showBonusVerifyDialog"
      @onClose="handleCloseBonusVerifyDialog"
    />

    <!-- Account / Login Dialog (抽离为独立组件) -->
    <user-login-dialog
      :visible.sync="showAccountDialog"
      :user-info="userInfo"
      @logged-in="handleUserLoggedIn"
    />

    <!-- Pricing Dialog -->
    <pricing-dialog
      :visible.sync="showPricingDialog"
    />
  </div>
</template>

<script>
  import NeedLoginDialog from "./components/NeedLoginDialog.vue";
  import CarouselLink from '@/components/CarouselLink.vue';
  import { randomMSec, formateDate } from "../common/utils";
  import { fetchJson, fetchPage } from "../common/fetchUtil";
  import BonusVerifyDialog from './components/BonusVerifyDialog.vue'
  import UserLoginDialog from './components/UserLoginDialog.vue'
  import PricingDialog from './components/PricingDialog.vue'
  import {
    stgGetLeadList,
    stgPushLeadByBatch,
    stgSetLeadList,
    stgSetParsingSetting,
    stgGetUserInfo,
    stgSetUserInfo,
    stgSetInstagramLoginInfo,
    stgClearUserInfo,
    stgClearAuthToken,
    stgSetFetchProgress,
    stgGetFetchProgress,
    stgClearFetchProgress,
  } from "../common/storage";
  import {
    sendEmailCode,
    emailLogin,
    fetchUserInfo,
    googleLogin as apiGoogleLogin,
  } from "../common/userApi";
  import {
    INS_API_HOST,
    COOLDOWN_SEC,
    RUN_STAT_RUNNING,
    RUN_STAT_STOPPED,
    RUN_STAT_COOLDOWN,
    RUN_STAT_FINISHED,
    LIMIT_ERROR,
    SYNC_LOGIN_STATUS,
    INS_QUERY_HASH,
  } from "../common/constants";
  import { getInstagramCookies, validatePostUrl } from "../util/utils";
  import { sendAliLog } from "@/util/alilog";

  const SHORTCODE_ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";

  export default {
    name: "App",
    components: { NeedLoginDialog, CarouselLink, BonusVerifyDialog, UserLoginDialog, PricingDialog },
    data() {
      return {
        logoImg: "",
        postUrl: "",
        intervalSec: 5,
        newIntervalSec: 5,
        riskyMessage: "High Risk For Your Account",
        exportType: 1,
        runningStat: RUN_STAT_STOPPED,
        errorMessage: "",
        coolDownSec: 0,
        pageEndCursor: "",
        totalComments: 0,
        mediaCommentCount: null,
        mediaV1Id: "",
        mediaPreviewComments: [],
        availabilityNotice: "",
        foundComments: 0,
        hasNextPage: true,
        fetchPageNum: 0,
        consecutiveEmptyPages: 0,
        showNeedLogin: false,
        showBonusVerifyDialog: false,
        commentList: [],
        limitReached: false,
        // 当前导出上限（用于进度条计算），默认按免费版 100
        exportLimit: 1e6,
        userInfo: null,
        userPayInfo: [],
        loadingUserInfo: false,
        showAccountDialog: false,
        showPricingDialog: false,
        hasSavedProgress: false,
        savedProgressComments: 0,
        RUN_STAT_STOPPED,
        RUN_STAT_RUNNING,
        RUN_STAT_COOLDOWN,
        RUN_STAT_FINISHED,
      };
    },
    created() {
      chrome.runtime.sendMessage({ code: SYNC_LOGIN_STATUS });
      this.initLoginState();
      this.checkPaymentCallback();
      
      // 监听页面关闭/刷新，自动保存进度
      window.addEventListener('beforeunload', this.handleBeforeUnload);
    },
    beforeDestroy() {
      window.removeEventListener('beforeunload', this.handleBeforeUnload);
    },
    async mounted() {
      this.logoImg = await chrome.runtime.getURL("icons/logo_128.png");
      document.getElementById("intervalSecInputRange")
        .addEventListener("mouseup", () => {
          if (this.intervalSec !== this.newIntervalSec) {
            sendAliLog('2j0055', { delay_time: this.intervalSec });
            this.newIntervalSec = this.intervalSec;
          }
        });
      
      // 检查是否有保存的进度
      const savedProgress = await this.checkSavedProgress();
      await this.restoreCachedComments(savedProgress);
      
      // 页面关闭前自动保存进度
      window.addEventListener('beforeunload', async (e) => {
        if (this.runningStat === RUN_STAT_RUNNING || this.runningStat === RUN_STAT_COOLDOWN) {
          await this.saveFetchProgress();
        }
      });
    },
    methods: {
      showErrorMessage(msg) {
        this.errorMessage = msg;
        this.runningStat = RUN_STAT_STOPPED;
      },
      showCoolDown(msg) {
        this.errorMessage = msg;
      },
      clearErrorMessage() {
        this.errorMessage = "";
      },
      async clearLastCommentData() {
        await stgSetLeadList([]);
        this.totalComments = 0;
        this.mediaCommentCount = null;
        this.mediaV1Id = "";
        this.mediaPreviewComments = [];
        this.availabilityNotice = "";
        this.foundComments = 0;
        this.commentList = [];
        this.limitReached = false;
        this.consecutiveEmptyPages = 0;
      },
      coolDown(initSec = 0) {
        if (initSec != 0) {
          this.coolDownSec = initSec;
          this.runningStat = RUN_STAT_COOLDOWN;
        }
        if (this.coolDownSec <= 0) {
          this.runningStat = RUN_STAT_RUNNING;
          this.clearErrorMessage();
          this.nextPage();
          return;
        }
        setTimeout(() => {
          this.coolDownSec--;
          this.coolDown();
        }, 1000);
      },
      async pauseLead() {
        sendAliLog('2j0071', {
          ig_post_url: this.postUrl,
          delay_time: this.intervalSec,
          total_num: this.totalComments,
          parsing_num: this.foundComments,
          parsing_state: this.runningStat,
        });
        this.runningStat = RUN_STAT_STOPPED;
        // 保存当前进度
        await this.saveFetchProgress();
        this.$message.success(`Paused at ${this.foundComments} comments. You can resume anytime.`);
      },
      async stopLead() {
        sendAliLog('2j0070', {
          ig_post_url: this.postUrl,
          delay_time: this.intervalSec,
          total_num: this.totalComments,
          parsing_num: this.foundComments,
          parsing_state: this.runningStat,
        });
        this.runningStat = RUN_STAT_STOPPED;
        // 清除进度
        await this.clearProgress();
        this.$message.info('Stopped and reset. All progress cleared.');
      },
      async clearProgress() {
        await stgClearFetchProgress();
        await this.clearLastCommentData();
        this.hasSavedProgress = false;
        this.savedProgressComments = 0;
        this.pageEndCursor = "";
        this.fetchPageNum = 0;
      },
      async saveFetchProgress() {
        if (!this.postUrl && this.commentList.length === 0) return;
        const progress = {
          postUrl: this.postUrl,
          postCode: this.postCode,
          pageEndCursor: this.pageEndCursor,
          totalComments: this.totalComments,
          mediaCommentCount: this.mediaCommentCount,
          mediaV1Id: this.mediaV1Id,
          mediaPreviewComments: this.mediaPreviewComments,
          availabilityNotice: this.availabilityNotice,
          foundComments: this.foundComments,
          hasNextPage: this.hasNextPage,
          fetchPageNum: this.fetchPageNum,
          intervalSec: this.intervalSec,
          consecutiveEmptyPages: this.consecutiveEmptyPages,
          timestamp: Date.now(),
        };
        await stgSetFetchProgress(progress);
        this.hasSavedProgress = true;
        this.savedProgressComments = this.foundComments;
      },
      async checkSavedProgress() {
        const progress = await stgGetFetchProgress();
        if (progress && progress.postUrl) {
          this.hasSavedProgress = true;
          this.savedProgressComments = progress.foundComments || 0;
          this.$message.info(`Found saved progress: ${this.savedProgressComments} comments from previous session`);
        }
        return progress;
      },
      async restoreCachedComments(progress = null) {
        const savedComments = await stgGetLeadList();
        if (!Array.isArray(savedComments) || savedComments.length === 0) return;

        this.commentList = savedComments;
        this.foundComments = Math.max(
          this.foundComments || 0,
          progress && progress.foundComments ? progress.foundComments : 0,
          savedComments.length
        );

        if (progress && progress.postUrl) {
          this.postUrl = this.postUrl || progress.postUrl;
          this.postCode = this.postCode || progress.postCode || "";
          this.totalComments = progress.totalComments || this.totalComments || savedComments.length;
          this.mediaCommentCount = progress.mediaCommentCount || this.mediaCommentCount;
          this.mediaV1Id = progress.mediaV1Id || this.mediaV1Id;
          this.mediaPreviewComments = progress.mediaPreviewComments || this.mediaPreviewComments;
          this.availabilityNotice = progress.availabilityNotice || this.availabilityNotice;
          this.hasNextPage = progress.hasNextPage !== undefined ? progress.hasNextPage : this.hasNextPage;
          this.pageEndCursor = progress.pageEndCursor || this.pageEndCursor;
          this.fetchPageNum = progress.fetchPageNum || this.fetchPageNum;
          this.intervalSec = progress.intervalSec || this.intervalSec;
          this.consecutiveEmptyPages = progress.consecutiveEmptyPages || this.consecutiveEmptyPages;
          return;
        }

        if (!this.hasSavedProgress && this.runningStat === RUN_STAT_STOPPED) {
          this.totalComments = this.totalComments || savedComments.length;
          this.runningStat = RUN_STAT_FINISHED;
        }
      },
      async syncInstagramLoginInfo() {
        try {
          const response = await new Promise((resolve) => {
            chrome.runtime.sendMessage({ code: SYNC_LOGIN_STATUS }, (res) => {
              if (chrome.runtime.lastError) {
                resolve(null);
                return;
              }
              resolve(res);
            });
          });

          if (response && response.cookie) return response.cookie;
        } catch (error) {
          console.warn('Failed to request Instagram login status from background:', error);
        }

        const cookie = await getInstagramCookies();
        await stgSetInstagramLoginInfo({ cookie, updatedAt: Date.now() });
        return cookie;
      },
      async markFetchFinished() {
        this.runningStat = RUN_STAT_FINISHED;
        await stgClearFetchProgress();
        this.hasSavedProgress = false;
        this.savedProgressComments = 0;
        await this.restoreCachedComments();
      },
      handleBeforeUnload(e) {
        // 如果正在抓取中，自动保存进度
        if (this.runningStat === RUN_STAT_RUNNING || this.runningStat === RUN_STAT_COOLDOWN) {
          this.saveFetchProgress();
          // 提示用户有未完成的任务
          e.preventDefault();
          e.returnValue = 'Export in progress. Your progress will be saved. Are you sure you want to leave?';
          return e.returnValue;
        }
      },
      async resumeFetch() {
        const progress = await stgGetFetchProgress();
        if (!progress || !progress.postUrl) {
          this.$message.error('No saved progress found');
          return;
        }
        
        // 恢复进度
        this.postUrl = progress.postUrl;
        this.postCode = progress.postCode;
        this.pageEndCursor = progress.pageEndCursor;
        this.totalComments = progress.totalComments;
        this.mediaCommentCount = progress.mediaCommentCount || null;
        this.mediaV1Id = progress.mediaV1Id || "";
        this.mediaPreviewComments = progress.mediaPreviewComments || [];
        this.availabilityNotice = progress.availabilityNotice || "";
        this.foundComments = progress.foundComments;
        this.hasNextPage = progress.hasNextPage;
        this.fetchPageNum = progress.fetchPageNum;
        this.intervalSec = progress.intervalSec || 5;
        this.consecutiveEmptyPages = progress.consecutiveEmptyPages || 0;
        
        // 恢复已保存的评论列表
        const savedComments = await stgGetLeadList();
        this.commentList = savedComments;
        
        this.$message.success(`Resuming from ${this.foundComments} comments...`);
        sendAliLog('2j0072', {
          ig_post_url: this.postUrl,
          resume_from: this.foundComments,
        });
        
        // 继续抓取
        this.runningStat = RUN_STAT_RUNNING;
        this.clearErrorMessage();
        setTimeout(() => { this.nextPage(); }, randomMSec(Math.ceil(this.intervalSec * 1000)));
      },
      async fetchLead() {
        // 所有功能需要先完成账号登录
        if (!this.isLoggedIn) {
          this.$message.warning("Please sign in to use this feature");
          this.showAccountDialog = true;
          return;
        }
        sendAliLog('2j0060', {
          ig_post_url: this.postUrl,
          delay_time: this.intervalSec,
          total_num: this.totalComments,
          parsing_num: this.foundComments,
        });
        const instagramCookie = await this.syncInstagramLoginInfo();
        if (!instagramCookie) {
          this.showNeedLogin = true;
          return;
        }
        this.clearErrorMessage();
        this.showNeedLogin = false;
        const result = validatePostUrl(this.postUrl);
        if (result.error && !result.postCode) {
          this.showErrorMessage(result.error);
          return;
        }
        this.postCode = result.postCode;
        if (!this.postCode) {
          this.showErrorMessage("Could not extract post code from URL. Please check the URL.");
          return;
        }
        this.runningStat = RUN_STAT_RUNNING;
        try {
          await this.clearLastCommentData();
          await stgClearFetchProgress(); // 清除旧进度
          this.hasSavedProgress = false;
          this.savedProgressComments = 0;
          await this.firstPage();
        } catch (error) {
          const errMsg = JSON.parse(error.message);
          this.showErrorMessage(errMsg.message);
        }
      },
      async firstPage() {
        let v = { shortcode: this.postCode, after: "", first: 50 };
        const encodedVars = encodeURIComponent(JSON.stringify(v)).replace(/%3A/gi, ':').replace(/%2C/gi, ',');
        let pageUrl = INS_API_HOST + "?query_hash=" + INS_QUERY_HASH + "&variables=" + encodedVars;
        let pageData;
        try {
          pageData = await fetchPage(pageUrl);
        } catch (error) {
          const errorMsg = JSON.parse(error.message);
          if (errorMsg.type === LIMIT_ERROR) {
            this.showCoolDown("");
            this.coolDown(COOLDOWN_SEC * 2);
          } else {
            this.showErrorMessage(errorMsg.message);
          }
          return;
        }
        let userList = [];
        try {
          const resultData = pageData.data.data.shortcode_media.edge_media_to_comment;
          this.pageEndCursor = resultData.page_info.end_cursor;
          this.totalComments = await this.syncMediaCommentCount(resultData.count);
          this.hasNextPage = resultData.page_info.has_next_page;
          userList = resultData.edges;
          
          // 详细日志
          console.log(`[First Page] Total comments: ${this.totalComments}, GraphQL count: ${resultData.count}, Fetched: ${userList.length}, hasNext: ${this.hasNextPage}, cursor: ${this.pageEndCursor ? 'exists' : 'null'}`);
          
          // 检查是否真的有数据返回
          if (!userList || userList.length === 0) {
            console.warn('[Warning] No data returned from first page');
            this.hasNextPage = false;
          }
        } catch (error) {
          console.error('[Error] Failed to parse first page comment data:', error);
          this.showCoolDown("");
          this.coolDown(COOLDOWN_SEC);
          return;
        }
        await this.handlerPageData(userList);
        
        // 使用改进的停止条件（与nextPage一致）
        const apiSaysNoMore = !this.hasNextPage && (!this.pageEndCursor || this.pageEndCursor === null);
        const noNewData = userList.length === 0;
        
        if (apiSaysNoMore || noNewData) {
          await this.supplementMissingCommentsFromV1();
          await this.markFetchFinished();
          
          // 计算未抓取的评论数量
          const missedComments = this.totalComments - this.foundComments;
          
          // 如果抓取数量明显少于总数，提示用户这是Instagram API限制
          if (missedComments > 100) {
            const percentage = Math.round((this.foundComments / this.totalComments) * 100);
            this.$message.warning(`Export completed: ${this.foundComments} comments collected (${percentage}% of ${this.totalComments} total). Instagram API has limits on fetching all comments. Missing ${missedComments} comments due to Instagram's restrictions.`);
            
            // 发送日志记录API限制情况
            sendAliLog('2j0091', {
              ig_post_url: this.postUrl,
              total_comments: this.totalComments,
              collected_comments: this.foundComments,
              missed_comments: missedComments,
              completion_rate: percentage,
              reason: 'Instagram API limit - first page check'
            });
          } else {
            this.$message.success(`Export completed! ${this.foundComments} comments collected.`);
          }
          return;
        }
        
        // 如果has_next_page为false但还有end_cursor，继续尝试抓取
        if (!this.hasNextPage && this.pageEndCursor) {
          console.log(`First page: continuing despite hasNextPage=false, cursor exists. Found: ${this.foundComments}/${this.totalComments}`);
        }
        
        setTimeout(() => { this.nextPage(); }, randomMSec(Math.ceil(this.intervalSec * 1000)));
      },
      async nextPage() {
        if (this.runningStat != RUN_STAT_RUNNING) return;
        let v = { shortcode: this.postCode, after: this.pageEndCursor, first: 50 };
        const encodedVars = encodeURIComponent(JSON.stringify(v)).replace(/%3A/gi, ':').replace(/%2C/gi, ',');
        let pageUrl = INS_API_HOST + "?query_hash=" + INS_QUERY_HASH + "&variables=" + encodedVars;
        let pageData;
        try {
          pageData = await fetchPage(pageUrl);
        } catch (error) {
          const errorMsg = JSON.parse(error.message);
          if (errorMsg.type === LIMIT_ERROR) {
            this.showCoolDown("");
            this.coolDown(COOLDOWN_SEC * 2);
          } else {
            this.showErrorMessage(errorMsg.message);
          }
          return;
        }
        let userList = [];
        try {
          const resultData = pageData.data.data.shortcode_media.edge_media_to_comment;
          this.pageEndCursor = resultData.page_info.end_cursor;
          this.totalComments = await this.syncMediaCommentCount(resultData.count);
          this.hasNextPage = resultData.page_info.has_next_page;
          userList = resultData.edges;
          
          // 详细日志
          console.log(`[Fetch Page ${this.fetchPageNum}] Total: ${this.totalComments}, GraphQL count: ${resultData.count}, Found: ${this.foundComments}, New: ${userList.length}, hasNext: ${this.hasNextPage}, cursor: ${this.pageEndCursor ? 'exists' : 'null'}`);
          
          // 检查是否真的有数据返回
          if (!userList || userList.length === 0) {
            console.warn('[Warning] No more data returned from API');
            this.consecutiveEmptyPages++;
          } else {
            this.consecutiveEmptyPages = 0; // 重置计数器
          }
        } catch (error) {
          console.error('[Error] Failed to parse comment data:', error);
          this.showCoolDown("");
          this.coolDown(COOLDOWN_SEC * 2);
          return;
        }
        await this.handlerPageData(userList);
        
        // 改进的停止条件：
        // 1. API明确表示没有下一页 AND end_cursor为空或null
        // 2. 或者已经达到总评论数
        // 3. 或者连续3次收到空数据（可能是真的没数据了）
        const apiSaysNoMore = !this.hasNextPage && (!this.pageEndCursor || this.pageEndCursor === null);
        const reachedTotal = this.foundComments >= this.totalComments;
        const tooManyEmptyPages = this.consecutiveEmptyPages >= 3;
        
        const shouldStop = apiSaysNoMore || reachedTotal || tooManyEmptyPages;
        
        if (shouldStop) {
          console.log(`[Stop] Stopping fetch - apiSaysNoMore: ${apiSaysNoMore}, reachedTotal: ${reachedTotal}, tooManyEmptyPages: ${tooManyEmptyPages}`);
          await this.supplementMissingCommentsFromV1();
          await this.markFetchFinished();
          
          // 计算未抓取的评论数量
          const missedComments = this.totalComments - this.foundComments;
          
          // 如果抓取数量明显少于总数，提示用户这是Instagram API限制
          if (missedComments > 100) {
            const percentage = Math.round((this.foundComments / this.totalComments) * 100);
            this.$message.warning(`Export completed: ${this.foundComments} comments collected (${percentage}% of ${this.totalComments} total). Instagram API has limits on fetching all comments. Missing ${missedComments} comments due to Instagram's restrictions.`);
            
            // 发送日志记录API限制情况
            sendAliLog('2j0091', {
              ig_post_url: this.postUrl,
              total_comments: this.totalComments,
              collected_comments: this.foundComments,
              missed_comments: missedComments,
              completion_rate: percentage,
              reason: `Instagram API limit - hasNextPage: ${this.hasNextPage}, endCursor: ${this.pageEndCursor ? 'exists' : 'null'}, emptyPages: ${this.consecutiveEmptyPages}, pages: ${this.fetchPageNum}`
            });
          } else {
            this.$message.success(`Export completed! ${this.foundComments} comments collected.`);
          }
          return;
        }
        
        // 如果has_next_page为false但还有end_cursor，继续尝试抓取
        if (!this.hasNextPage && this.pageEndCursor) {
          console.log(`Continuing despite hasNextPage=false, cursor exists. Found: ${this.foundComments}/${this.totalComments}`);
        }
        
        this.fetchPageNum++;
        if (this.fetchPageNum % 100 == 0) {
          this.coolDown(COOLDOWN_SEC);
          return;
        }
        setTimeout(() => { this.nextPage(); }, randomMSec(Math.ceil(this.intervalSec * 1000)));
      },
      formatCommentNode(node, meta = {}) {
        const owner = node && node.owner ? node.owner : {};
        const userName = owner.username || "";
        return {
          id: owner.id || "",
          commentId: node && node.id ? node.id : "",
          commentType: meta.commentType || "comment",
          parentCommentId: meta.parentCommentId || "",
          parentUserName: meta.parentUserName || "",
          userName,
          text: node && node.text ? node.text : "",
          profileUrl: userName ? "https://www.instagram.com/" + userName + "/" : "",
          avatarUrl: owner.profile_pic_url || "",
          date: node && node.created_at ? formateDate(node.created_at * 1000) : "",
        };
      },
      flattenCommentEdges(userList) {
        let formatUserList = [];
        for (let i = 0; i < userList.length; i++) {
          const commentNode = userList[i] && userList[i].node;
          if (!commentNode) continue;

          formatUserList.push(this.formatCommentNode(commentNode));

          const threadedComments = commentNode.edge_threaded_comments || {};
          const replyEdges = threadedComments.edges || [];
          const parentCommentId = commentNode.id || "";
          const parentUserName = commentNode.owner && commentNode.owner.username ? commentNode.owner.username : "";
          for (let j = 0; j < replyEdges.length; j++) {
            const replyNode = replyEdges[j] && replyEdges[j].node;
            if (!replyNode) continue;
            formatUserList.push(this.formatCommentNode(replyNode, {
              commentType: "reply",
              parentCommentId,
              parentUserName,
            }));
          }

          if (threadedComments.count > replyEdges.length) {
            console.warn(`[Warning] Comment ${parentCommentId} has ${threadedComments.count} replies, but Instagram returned ${replyEdges.length} inline replies.`);
          }
        }
        return formatUserList;
      },
      shortcodeToMediaId(shortcode) {
        let mediaId = 0n;
        for (let i = 0; i < shortcode.length; i++) {
          const index = SHORTCODE_ALPHABET.indexOf(shortcode[i]);
          if (index < 0) return "";
          mediaId = mediaId * 64n + BigInt(index);
        }
        return mediaId.toString();
      },
      async fetchMediaCommentCount() {
        if (this.mediaCommentCount !== null && this.mediaV1Id) return this.mediaCommentCount;

        const mediaId = this.shortcodeToMediaId(this.postCode);
        if (!mediaId) return null;

        try {
          const mediaUrl = `https://www.instagram.com/api/v1/media/${mediaId}/info/`;
          const mediaData = await fetchJson(mediaUrl);
          const items = mediaData && mediaData.data && mediaData.data.items ? mediaData.data.items : [];
          this.mediaV1Id = items[0] && (items[0].id || items[0].pk)
            ? String(items[0].id || items[0].pk)
            : this.mediaV1Id;
          this.mediaPreviewComments = this.extractMediaPreviewComments(items[0]);
          const commentCount = items[0] && Number(items[0].comment_count);
          this.mediaCommentCount = Number.isFinite(commentCount) ? commentCount : null;
          return this.mediaCommentCount;
        } catch (error) {
          console.warn("[Warning] Failed to fetch media comment_count:", error);
          return this.mediaCommentCount;
        }
      },
      async syncMediaCommentCount(graphqlCount) {
        const mediaCommentCount = await this.fetchMediaCommentCount();
        if (mediaCommentCount !== null && mediaCommentCount > graphqlCount) {
          console.log(`[Media Info] Using media comment_count ${mediaCommentCount} instead of GraphQL count ${graphqlCount}`);
          return mediaCommentCount;
        }
        return graphqlCount;
      },
      extractMediaPreviewComments(mediaItem) {
        if (!mediaItem) return this.mediaPreviewComments || [];

        const previewSources = [
          mediaItem.preview_comments,
          mediaItem.comments,
          mediaItem.comment_preview,
          mediaItem.comment_inform_treatment && mediaItem.comment_inform_treatment.preview_comments,
        ];
        const comments = [];
        const seenIds = new Set();

        for (let i = 0; i < previewSources.length; i++) {
          const source = Array.isArray(previewSources[i]) ? previewSources[i] : [];
          for (let j = 0; j < source.length; j++) {
            const id = source[j] && (source[j].pk || source[j].id);
            if (id && seenIds.has(String(id))) continue;
            comments.push(source[j]);
            if (id) seenIds.add(String(id));
          }
        }

        return comments.length > 0 ? comments : (this.mediaPreviewComments || []);
      },
      async fetchInstagramV1(pathAndQuery) {
        const cleanPath = pathAndQuery.replace(/^\/+/, "");
        const urls = [
          `https://www.instagram.com/api/v1/${cleanPath}`,
          `https://i.instagram.com/api/v1/${cleanPath}`,
        ];
        let lastError = null;

        for (let i = 0; i < urls.length; i++) {
          try {
            return await fetchJson(urls[i]);
          } catch (error) {
            lastError = error;
            console.warn(`[Warning] Instagram V1 request failed: ${urls[i]}`, error);
          }
        }

        throw lastError;
      },
      formatV1CommentNode(comment, meta = {}) {
        const owner = comment && (comment.user || comment.owner) ? (comment.user || comment.owner) : {};
        const userName = owner.username || "";
        const createdAt = Number(comment && (comment.created_at || comment.created_at_utc));
        return {
          id: owner.pk || owner.id || comment.user_id || "",
          commentId: comment && (comment.pk || comment.id) ? String(comment.pk || comment.id) : "",
          commentType: meta.commentType || "comment",
          parentCommentId: meta.parentCommentId || "",
          parentUserName: meta.parentUserName || "",
          userName,
          text: comment && comment.text ? comment.text : "",
          profileUrl: userName ? "https://www.instagram.com/" + userName + "/" : "",
          avatarUrl: owner.profile_pic_url || "",
          date: createdAt ? formateDate(createdAt * 1000) : "",
        };
      },
      async fetchV1CommentReplies(mediaId, parentComment) {
        const parentCommentId = parentComment && (parentComment.pk || parentComment.id) ? String(parentComment.pk || parentComment.id) : "";
        if (!parentCommentId) return [];

        const parentUser = parentComment.user || parentComment.owner || {};
        const parentUserName = parentUser.username || "";
        let minId = "";
        let replies = [];
        for (let page = 0; page < 10; page++) {
          const params = new URLSearchParams();
          if (minId) params.set("min_id", minId);
          const query = params.toString();
          const result = await this.fetchInstagramV1(`media/${mediaId}/comments/${parentCommentId}/inline_child_comments/${query ? "?" + query : ""}`);
          const data = result && result.data ? result.data : {};
          const childComments = data.child_comments || [];
          for (let i = 0; i < childComments.length; i++) {
            replies.push(this.formatV1CommentNode(childComments[i], {
              commentType: "reply",
              parentCommentId,
              parentUserName,
            }));
          }

          const nextCursor = data.next_min_child_cursor || "";
          if (!data.has_more_head_child_comments || !nextCursor || nextCursor === minId) break;
          minId = nextCursor;
        }
        return replies;
      },
      async flattenV1Comment(comment, mediaId) {
        const rows = [this.formatV1CommentNode(comment)];
        const parentCommentId = comment && (comment.pk || comment.id) ? String(comment.pk || comment.id) : "";
        const parentUser = comment.user || comment.owner || {};
        const parentUserName = parentUser.username || "";
        const childComments = comment.child_comments || comment.preview_child_comments || [];

        for (let i = 0; i < childComments.length; i++) {
          rows.push(this.formatV1CommentNode(childComments[i], {
            commentType: "reply",
            parentCommentId,
            parentUserName,
          }));
        }

        const childCommentCount = Number(comment.child_comment_count || comment.child_comments_count || 0);
        if (childCommentCount > childComments.length) {
          const extraReplies = await this.fetchV1CommentReplies(mediaId, comment);
          const existingIds = new Set(rows.map(item => item.commentId).filter(Boolean));
          for (let i = 0; i < extraReplies.length; i++) {
            if (extraReplies[i].commentId && existingIds.has(extraReplies[i].commentId)) continue;
            rows.push(extraReplies[i]);
            existingIds.add(extraReplies[i].commentId);
          }
        }

        return rows;
      },
      async fetchV1Comments(mediaId, targetCount) {
        let rows = [];
        let maxId = "";
        let minId = "";
        const seenIds = new Set();

        const previewComments = this.mediaPreviewComments || [];
        for (let i = 0; i < previewComments.length; i++) {
          const flattened = await this.flattenV1Comment(previewComments[i], mediaId);
          for (let j = 0; j < flattened.length; j++) {
            const commentId = flattened[j].commentId;
            if (commentId && seenIds.has(commentId)) continue;
            rows.push(flattened[j]);
            if (commentId) seenIds.add(commentId);
          }
        }

        for (let page = 0; page < 10; page++) {
          const params = new URLSearchParams({
            can_support_threading: "true",
            permalink_enabled: "false",
          });
          if (maxId) {
            params.set("max_id", maxId);
          } else if (minId) {
            params.set("min_id", minId);
          }

          const result = await this.fetchInstagramV1(`media/${mediaId}/comments/?${params.toString()}`);
          const data = result && result.data ? result.data : {};
          const comments = [
            ...(data.preview_comments || []),
            ...(data.comments || []),
          ];

          for (let i = 0; i < comments.length; i++) {
            const flattened = await this.flattenV1Comment(comments[i], mediaId);
            for (let j = 0; j < flattened.length; j++) {
              const commentId = flattened[j].commentId;
              if (commentId && seenIds.has(commentId)) continue;
              rows.push(flattened[j]);
              if (commentId) seenIds.add(commentId);
            }
          }

          if (targetCount && rows.length >= targetCount) break;

          const nextMaxId = data.next_max_id || data.max_id || "";
          const nextMinId = data.next_min_id || data.min_id || "";
          if (data.has_more_comments && nextMaxId && nextMaxId !== maxId) {
            maxId = nextMaxId;
          } else if (data.has_more_headload_comments && nextMinId && nextMinId !== minId) {
            maxId = "";
            minId = nextMinId;
          } else {
            break;
          }
        }

        return rows;
      },
      async supplementMissingCommentsFromV1() {
        if (this.foundComments >= this.totalComments) return;

        await this.fetchMediaCommentCount();
        const mediaId = this.mediaV1Id || this.shortcodeToMediaId(this.postCode);
        if (!mediaId) return;

        try {
          const v1Rows = await this.fetchV1Comments(mediaId, this.totalComments);
          console.log(`[V1 Comments] Loaded ${v1Rows.length} rows from media ${mediaId}. Preview: ${(this.mediaPreviewComments || []).length}. Existing: ${this.commentList.length}/${this.totalComments}`);
          const existingIds = new Set(this.commentList.map(item => item.commentId).filter(Boolean));
          const maxLimit = this.isProUser ? 1e006 : 1e6;
          const remainingSlots = Math.max(maxLimit - this.foundComments, 0);
          let missingRows = [];

          for (let i = 0; i < v1Rows.length; i++) {
            const commentId = v1Rows[i].commentId;
            if (commentId && existingIds.has(commentId)) continue;
            missingRows.push(v1Rows[i]);
            if (commentId) existingIds.add(commentId);
            if (missingRows.length >= remainingSlots || this.foundComments + missingRows.length >= this.totalComments) break;
          }

          if (missingRows.length > 0) {
            this.foundComments += missingRows.length;
            this.commentList.push(...missingRows);
            await stgPushLeadByBatch(missingRows);
            console.log(`[V1 Comments] Supplemented ${missingRows.length} comments. Found: ${this.foundComments}/${this.totalComments}`);
          } else {
            console.warn(`[V1 Comments] No new comments found. V1 rows: ${v1Rows.length}, existing IDs: ${existingIds.size}`);
            if (this.totalComments > this.foundComments) {
              this.availabilityNotice = `Instagram data may be delayed. Please use the actual collected count (${this.foundComments}) as the final result.`;
            }
          }
        } catch (error) {
          console.warn("[Warning] Failed to supplement comments from V1 API:", error);
        }
      },
      async handlerPageData(userList) {
        let formatUserList = this.flattenCommentEdges(userList);
        let count = this.foundComments + formatUserList.length;
        
        // 根据用户的实际支付状态判断导出上限
        const isPro = this.isProUser;
        const maxLimit = isPro ? 1e006 : 1e6;
        this.exportLimit = maxLimit;

        // 免费用户：限制1e6条
        if (count >= 1e6 && !isPro) {
          if (this.foundComments < 1e6) {
            formatUserList = formatUserList.slice(0, 1e6 - this.foundComments);
          } else {
            formatUserList = [];
          }
          this.limitReached = true;
          this.stopLead();
          this.showPricingDialog = true;
        } 
        // Pro用户：限制1,000K条
        else if (count >= 1e006 && isPro) {
          if (this.foundComments < 1e006) {
            formatUserList = formatUserList.slice(0, 1e006 - this.foundComments);
          } else {
            formatUserList = [];
          }
          this.limitReached = true;
          this.stopLead();
          this.$message.info('Export limit reached');
        }

        this.foundComments += formatUserList.length;
        this.commentList.push(...formatUserList);
        await stgPushLeadByBatch(formatUserList);
        
        // 每10页保存一次进度，防止页面刷新丢失数据
        if (this.fetchPageNum % 10 === 0) {
          await this.saveFetchProgress();
        }
      },
      async exportExcel() {
        if (!this.isLoggedIn) {
          this.$message.warning("Please sign in to export data");
          this.showAccountDialog = true;
          return;
        }
        let XLSX = require("xlsx");
        let userList = await stgGetLeadList();
        if (!userList.length) {
          this.$message.warning("No comments to export");
          return;
        }
        this.foundComments = Math.max(this.foundComments, userList.length);
        sendAliLog('2j0100', { ig_post_url: this.postUrl, delay_time: this.intervalSec, total_num: this.totalComments || userList.length, parsing_num: userList.length, parsing_state: this.runningStat });
        let finalData = [];
        for (let i = 0; i < userList.length; i++) {
          let tmp = {};
          tmp["id"] = userList[i].id;
          tmp["userName"] = userList[i].userName;
          tmp["text"] = userList[i].text;
          tmp["profileUrl"] = userList[i].profileUrl;
          tmp["avatarUrl"] = userList[i].avatarUrl;
          tmp["date"] = userList[i].date;
          tmp["commentId"] = userList[i].commentId || "";
          tmp["commentType"] = userList[i].commentType || "comment";
          tmp["parentCommentId"] = userList[i].parentCommentId || "";
          tmp["parentUserName"] = userList[i].parentUserName || "";
          finalData.push(tmp);
        }
        const ws = XLSX.utils.json_to_sheet(finalData);
        ws["!cols"] = [{ wch: 25 }, { wch: 25 }, { wch: 50 }, { wch: 40 }, { wch: 50 }, { wch: 25 }, { wch: 25 }, { wch: 14 }, { wch: 25 }, { wch: 25 }];
        const wb = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(wb, ws, "sheet1");
        XLSX.writeFile(wb, this.generateTitle("xlsx"));
      },
      async exportCSV() {
        if (!this.isLoggedIn) {
          this.$message.warning("Please sign in to export data");
          this.showAccountDialog = true;
          return;
        }
        let userList = await stgGetLeadList();
        if (!userList.length) {
          this.$message.warning("No comments to export");
          return;
        }
        this.foundComments = Math.max(this.foundComments, userList.length);
        sendAliLog('2j0100', { ig_post_url: this.postUrl, delay_time: this.intervalSec, total_num: this.totalComments || userList.length, parsing_num: userList.length, parsing_state: this.runningStat });
        let head = ["id", "userName", "text", "profileUrl", "avatarUrl", "date", "commentId", "commentType", "parentCommentId", "parentUserName"];
        let data = [];
        for (let i = 0; i < userList.length; i++) {
          data.push([userList[i].id, userList[i].userName, userList[i].text, userList[i].profileUrl, userList[i].avatarUrl, userList[i].date, userList[i].commentId || "", userList[i].commentType || "comment", userList[i].parentCommentId || "", userList[i].parentUserName || ""]);
        }
        this.saveCSV(head, data);
      },
      format(data) {
        return String(data).replace(/"/g, '""').replace(/(^[\s\S]*$)/, '"$1"');
      },
      generateTitle(fileType = "csv") {
        return `${this.postCode}.${fileType}`;
      },
      saveCSV(head, data) {
        let wordSeparator = ",";
        let lineSeparator = "\n";
        let headBOM = "\ufeff";
        let reTitle = this.generateTitle();
        let headStr = head ? head.map((item) => this.format(item)).join(wordSeparator) + lineSeparator : "";
        let dataStr = data ? data.map((row) => row.map((item) => this.format(item)).join(wordSeparator)).join(lineSeparator) : "";
        let a = document.createElement("a");
        a.href = "data:text/csv;charset=utf-8," + headBOM + encodeURIComponent(headStr + dataStr);
        a.download = reTitle;
        a.click();
      },
      onBlurInput(type) {
        if (type === "postUrl") {
          sendAliLog('2j0050', { ig_post_url: this.postUrl });
        } else if (type === "intervalSec") {
          this.newIntervalSec = this.intervalSec;
          sendAliLog('2j0055', { delay_time: this.intervalSec });
        }
      },
      proxyImg(url) {
        if (!url) return '';
        return 'https://cdn.getwebooster.workers.dev/' + url;
      },
      sendUpgradeLog() {
        sendAliLog('2j0130');
      },
      handleUpgradeClick() {
        this.sendUpgradeLog();
        if (!this.isLoggedIn) {
          this.$message.warning("Please sign in to upgrade");
          this.showAccountDialog = true;
          return;
        }
        this.showPricingDialog = true;
      },
      clickContactUs() {
        sendAliLog('2j0105');
      },
      handleShowBonusVerify() {
        this.showBonusDialog = false;
        this.showBonusVerifyDialog = true;
      },
      handleCloseBonusVerifyDialog() {
        this.showBonusVerifyDialog = false;
        this.restoreCachedComments();
      },
      async initLoginState() {
        // 初始化时先认为未登录，只有后端 /info 校验通过后才标记为已登录
        this.userInfo = null;
        this.userPayInfo = [];
        this.loadingUserInfo = true;
        try {
          const res = await fetchUserInfo();
          const raw = res && res.data ? res.data : res;
          const user = (raw && raw.user_info) || raw || null;
          const payInfo = (raw && raw.pay_info) || [];
          const hasValidUser =
            !!(user &&
              (user.email ||
               user.username ||
               user.userName ||
               user.name ||
               user.id));
          if (hasValidUser) {
            this.userInfo = user;
            await stgSetUserInfo(user);
            this.userPayInfo = payInfo;
          } else {
            // 后端未返回有效用户信息时，视为未登录
            this.userInfo = null;
            this.userPayInfo = [];
            await stgClearUserInfo();
            await stgClearAuthToken();
          }
        } catch (e) {
          // /info 调用失败时，视为未登录状态，清理本地缓存，避免 UI 误判
          this.userInfo = null;
          this.userPayInfo = [];
          await stgClearUserInfo();
          await stgClearAuthToken();
        } finally {
          this.loadingUserInfo = false;
        }
      },
      handleUserLoggedIn(payload) {
        const user = (payload && (payload.user || payload.user_info)) || payload || null;
        const payInfo = (payload && payload.pay_info) || [];
        const hasValidUser =
          !!(user &&
            (user.email ||
             user.username ||
             user.userName ||
             user.name ||
             user.id));
        if (hasValidUser) {
          this.userInfo = user;
          stgSetUserInfo(user);
        }
        this.userPayInfo = payInfo;
        this.showAccountDialog = false;
      },
      async checkPaymentCallback() {
        const urlParams = new URLSearchParams(window.location.search);
        const paymentStatus = urlParams.get('payment_status');
        if (paymentStatus === 'success' || paymentStatus === 'completed') {
          this.$message.success("Payment successful! Updating your account...");
          try {
            const res = await fetchUserInfo();
            const raw = res && res.data ? res.data : res;
            const user = (raw && raw.user_info) || raw || null;
            const payInfo = (raw && raw.pay_info) || [];
            if (user) {
              this.userInfo = user;
              await stgSetUserInfo(user);
              this.userPayInfo = payInfo;
              this.$message.success("Welcome to Pro! Your account has been upgraded.");
            }
          } catch (e) {
            this.$message.error("Failed to update account status");
          }
          const newUrl = window.location.pathname;
          window.history.replaceState({}, document.title, newUrl);
        }
      },
      async onLogout() {
        this.userInfo = null;
        this.userPayInfo = [];
        await stgClearUserInfo();
        await stgClearAuthToken();
        await new Promise(resolve => chrome.storage.local.remove(['userToken', 'userEmail', 'google_access_token'], resolve));
        this.loginCode = "";
        this.$message.success("Signed out");
        this.showAccountDialog = false;
      },
    },
    computed: {
      parsingSetting() {
        return {
          ig_post_url: this.postUrl,
          delay_time: this.intervalSec,
          total_num: this.totalComments,
          parsing_num: this.foundComments,
          parsing_state: this.runningStat,
        };
      },
      isLoggedIn() {
        const u = this.userInfo || null;
        if (!u) return false;
        return !!(u.email || u.username || u.userName || u.name || u.id);
      },
      isProUser() {
        return Array.isArray(this.userPayInfo) && this.userPayInfo.length > 0;
      },
      displayUserName() {
        if (!this.userInfo) return "";
        return this.userInfo.email || this.userInfo.username || this.userInfo.userName || this.userInfo.name || "";
      },
      displayMaskedUser() {
        const raw = this.displayUserName;
        if (!raw) return "";
        // 仅对邮箱做中间脱敏，其它类型用户名原样展示
        const atIndex = raw.indexOf("@");
        if (atIndex <= 0) return raw;
        const local = raw.slice(0, atIndex);
        const domain = raw.slice(atIndex);
        if (local.length <= 3) {
          return local[0] + "***" + domain;
        }
        return local.slice(0, 3) + "***" + domain;
      },
      canStartParsing() {
        const hasUrl = !!(this.postUrl && this.postUrl.trim());
        return hasUrl && (this.runningStat === RUN_STAT_STOPPED || this.runningStat === RUN_STAT_FINISHED);
      },
      canPauseParsing() {
        return this.runningStat === RUN_STAT_RUNNING || this.runningStat === RUN_STAT_COOLDOWN;
      },
      progressPercent() {
        // 达到限制后，直接显示 100%
        if (this.limitReached) {
          return 100;
        }

        // 没有任何数据时展示为 0%
        if (!this.totalComments && !this.foundComments) {
          return 0;
        }

        // 有些帖子评论数远大于免费导出上限（100 / 200），
        // 此处对进度条采用「导出上限」作为基准，让进度更加直观。
        const baseLimit = this.exportLimit || 1e6;
        const denominator =
          this.totalComments > 0
            ? Math.min(this.totalComments, baseLimit)
            : baseLimit;

        if (!denominator) return 0;

        const percent = (this.foundComments / denominator) * 100;
        return Math.max(0, Math.min(100, Math.round(percent)));
      },
    },
    watch: {
      parsingSetting() {
        stgSetParsingSetting({
          ig_post_url: this.postUrl,
          delay_time: this.intervalSec,
          total_num: this.totalComments,
          parsing_num: this.foundComments,
          parsing_state: this.runningStat,
        });
      },
    },
  };
</script>

