@keyframes sparkle {
  0%, 100% { transform: scale(1) rotate(0deg); }
  50% { transform: scale(1.1) rotate(5deg); }
}

/* ─── Body Layout ─── */
.app-body {
  display: flex;
  gap: 20px;
  padding: 24px 32px 0;
  align-items: stretch;
}

/* ─── Panels ─── */
.panel {
  background: #ffffff;
  border: 1px solid #e9ecef;
  border-radius: 12px;
  padding: 24px;
  box-shadow: 0 1px 3px rgba(15,23,42,0.06), 0 4px 16px rgba(15,23,42,0.03);
}

.panel-left {
  flex: 1 1 0;
  min-width: 0;
}

.panel-right-col {
  width: 300px;
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  gap: 0;
  background: #ffffff;
  border: 1px solid #e9ecef;
  border-radius: 12px;
  padding: 24px;
  box-shadow: 0 1px 3px rgba(15,23,42,0.06), 0 4px 16px rgba(15,23,42,0.03);
}

/* 右侧列内的小块不再单独成卡，避免双边框与空白 */
.panel-right-col .panel {
  background: transparent;
  border: none;
  box-shadow: none;
  padding: 0 0 16px;
  border-radius: 0;
}

.panel-right-col .panel:last-of-type {
  padding-bottom: 0;
  flex: 1;
  display: flex;
  flex-direction: column;
  min-height: 0;
}

.panel-right-col .panel + .panel {
  border-top: 1px solid #e9ecef;
  padding-top: 16px;
}

.panel-right-col .app-footer {
  margin-top: auto;
  padding-top: 16px;
  border-top: 1px solid #e9ecef;
}

.panel-header {
  margin-bottom: 20px;
}

.panel-title {
  font-size: 15px;
  font-weight: 700;
  color: #0f172a;
  letter-spacing: -0.1px;
}

.panel-desc {
  font-size: 12px;
  color: #64748b;
  margin-top: 3px;
}

/* ─── Form Components ─── */
.form-section {
  margin-bottom: 20px;
}

.form-label {
  display: block;
  font-size: 13px;
  font-weight: 600;
  color: #334155;
  margin-bottom: 6px;
  letter-spacing: 0.1px;
}

.form-label-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 6px;
}

.form-input {
  width: 100%;
  height: 38px;
  padding: 0 12px;
  border: 1.5px solid #e2e8f0;
  border-radius: 8px;
  font-size: 13px;
  color: #0f172a;
  background: #f8fafc;
  transition: border-color 0.15s, box-shadow 0.15s, background-color 0.15s;
  outline: none;
}

.form-input:hover {
  border-color: #cbd5e1;
  background: #ffffff;
}

.form-input:focus {
  border-color: #6366f1;
  box-shadow: 0 0 0 3px rgba(99,102,241,0.12);
  background: #ffffff;
}

.form-hint {
  font-size: 12px;
  color: #94a3b8;
  margin-top: 5px;
}

.form-note {
  display: flex;
  gap: 6px;
  align-items: flex-start;
  margin-top: 8px;
  padding: 8px 10px;
  background: #fffbeb;
  border: 1px solid #fef3c7;
  border-radius: 6px;
  font-size: 11px;
  color: #92400e;
  line-height: 1.4;
}

.saved-progress-hint {
  display: flex;
  gap: 8px;
  align-items: flex-start;
  margin-top: 12px;
  padding: 10px 12px;
  background: #f0fdf4;
  border: 1px solid #bbf7d0;
  border-radius: 8px;
  font-size: 12px;
  color: #15803d;
  line-height: 1.5;
  font-weight: 500;
}

.auto-save-hint {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: 8px;
  font-size: 11px;
  color: #6366f1;
  font-weight: 500;
}

.auto-save-icon {
  flex-shrink: 0;
  animation: pulse-subtle 2s ease-in-out infinite;
}

.api-limit-notice {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: 6px;
  padding: 6px 8px;
  background: #fffbeb;
  border: 1px solid #fef3c7;
  border-radius: 6px;
  font-size: 10px;
  color: #92400e;
  line-height: 1.4;
}

.api-limit-notice svg {
  flex-shrink: 0;
  color: #f59e0b;
}

@keyframes pulse-subtle {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.6; }
}

/* ─── Range Slider ─── */
.range-row {
  display: flex;
  align-items: center;
  gap: 10px;
}

.range-input {
  flex: 1;
  -webkit-appearance: none;
  appearance: none;
  height: 4px;
  border-radius: 99px;
  background: #e2e8f0;
  cursor: pointer;
  outline: none;
}

.range-input::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: #6366f1;
  border: 2.5px solid #ffffff;
  box-shadow: 0 1px 4px rgba(99,102,241,0.4);
  cursor: pointer;
}

.range-input::-moz-range-thumb {
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: #6366f1;
  border: 2.5px solid #ffffff;
  box-shadow: 0 1px 4px rgba(99,102,241,0.4);
  cursor: pointer;
}

.number-input {
  width: 72px;
  height: 36px;
  padding: 0 8px;
  border: 1.5px solid #e2e8f0;
  border-radius: 8px;
  font-size: 13px;
  color: #0f172a;
  background: #f8fafc;
  outline: none;
  text-align: center;
  transition: border-color 0.15s, box-shadow 0.15s;
  flex-shrink: 0;
}

.number-input:focus {
  border-color: #6366f1;
  box-shadow: 0 0 0 3px rgba(99,102,241,0.12);
  background: #ffffff;
}

.delay-badge {
  display: inline-flex;
  align-items: center;
  padding: 2px 8px;
  border-radius: 99px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.2px;
}

.delay-badge-safe {
  background: #dcfce7;
  color: #15803d;
}

.delay-badge-warn {
  background: #fff7ed;
  color: #c2410c;
}

/* ─── Risk Message ─── */
.risk-msg {
  font-size: 12px;
  color: #ef4444;
  margin: 4px 0 0;
  font-weight: 500;
}

/* ─── Action Row ─── */
.action-row {
  display: flex;
  gap: 10px;
  margin-top: 8px;
  flex-wrap: wrap;
}

/* ─── Buttons ─── */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 38px;
  padding: 0 20px;
  border-radius: 8px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  border: none;
  outline: none;
  transition: background-color 0.15s, box-shadow 0.15s, opacity 0.15s, transform 0.08s;
  letter-spacing: 0.1px;
}

.btn:active:not(:disabled) { transform: scale(0.98); }

.btn-primary {
  background: #6366f1;
  color: #ffffff;
  box-shadow: 0 2px 8px rgba(99,102,241,0.35);
}

.btn-primary:hover:not(:disabled) {
  background: #4f46e5;
  box-shadow: 0 4px 14px rgba(99,102,241,0.45);
}

.btn-danger {
  background: #ef4444;
  color: #ffffff;
  box-shadow: 0 2px 8px rgba(239,68,68,0.3);
}

.btn-danger:hover:not(:disabled) {
  background: #dc2626;
}

.btn-warning {
  background: #f59e0b;
  color: #ffffff;
  box-shadow: 0 2px 8px rgba(245,158,11,0.3);
}

.btn-warning:hover:not(:disabled) {
  background: #d97706;
}

.btn-success {
  background: #10b981;
  color: #ffffff;
  box-shadow: 0 2px 8px rgba(16,185,129,0.3);
}

.btn-success:hover:not(:disabled) {
  background: #059669;
  box-shadow: 0 4px 14px rgba(16,185,129,0.4);
}

.btn-disabled {
  background: #f1f5f9;
  color: #94a3b8;
  border: 1.5px solid #e2e8f0;
  cursor: not-allowed;
}

.btn-outline {
  background: transparent;
  color: #6366f1;
  border: 1.5px solid #6366f1;
}

.btn-outline:hover {
  background: #f0f0fe;
}

.btn-ghost {
  background: transparent;
  color: #64748b;
  border: none;
  font-size: 12px;
  padding: 0 8px;
  height: 28px;
  border-radius: 6px;
}

.btn-ghost:hover {
  background: #f1f5f9;
  color: #334155;
}

.btn-sm {
  height: 32px;
  padding: 0 14px;
  font-size: 12px;
  border-radius: 7px;
}

.btn-block {
  width: 100%;
}

.mt-8 { margin-top: 8px; }
.mt-16 { margin-top: 16px; }

/* ─── Google Button ─── */
.btn-google {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 42px;
  padding: 0 16px;
  background: #ffffff;
  border: 1.5px solid #e2e8f0;
  border-radius: 8px;
  font-size: 14px;
  font-weight: 600;
  color: #334155;
  cursor: pointer;
  transition: background-color 0.15s, border-color 0.15s, box-shadow 0.15s;
  outline: none;
}

.btn-google:hover:not(:disabled) {
  background: #f8fafc;
  border-color: #cbd5e1;
  box-shadow: 0 2px 8px rgba(15,23,42,0.08);
}

.btn-google:disabled {
  opacity: 0.65;
  cursor: not-allowed;
}

/* ─── Progress Panel ─── */
.stat-list {
  display: flex;
  flex-direction: column;
  gap: 0;
}

.stat-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 0;
  border-bottom: 1px solid #f1f5f9;
}

.stat-item:last-child { border-bottom: none; }

.stat-label {
  font-size: 13px;
  color: #64748b;
}

.stat-value {
  font-size: 13px;
  color: #334155;
  font-weight: 500;
}

.stat-num {
  font-weight: 700;
  color: #0f172a;
}

.stat-highlight {
  color: #6366f1;
}

.stat-error {
  color: #ef4444;
  font-size: 12px;
  max-width: 160px;
  text-align: right;
}

/* Status tags */
.stat-tag {
  display: inline-flex;
  align-items: center;
  padding: 2px 9px;
  border-radius: 99px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.2px;
}

.stat-tag-neutral { background: #f1f5f9; color: #64748b; }
.stat-tag-blue    { background: #eff6ff; color: #2563eb; }
.stat-tag-yellow  { background: #fffbeb; color: #d97706; }
.stat-tag-green   { background: #f0fdf4; color: #16a34a; }
.stat-tag-orange  { background: #fff7ed; color: #ea580c; }

/* Progress bar */
.progress-bar-wrap {
  height: 4px;
  background: #f1f5f9;
  border-radius: 99px;
  margin-top: 14px;
  overflow: hidden;
}

.progress-bar-fill {
  height: 100%;
  background: linear-gradient(90deg, #6366f1, #8b5cf6);
  border-radius: 99px;
  transition: width 0.5s ease;
}

/* ─── Export Panel ─── */
.export-btn-group {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.btn-export {
  height: 40px;
  font-size: 13px;
  font-weight: 600;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  border: none;
  outline: none;
  transition: background 0.15s, box-shadow 0.15s, transform 0.08s;
}

.btn-export:active:not(:disabled) { transform: scale(0.98); }

.btn-export-csv {
  background: #6366f1;
  color: #ffffff;
  box-shadow: 0 2px 8px rgba(99,102,241,0.3);
}

.btn-export-csv:hover {
  background: #4f46e5;
  box-shadow: 0 4px 14px rgba(99,102,241,0.4);
}

.btn-export-excel {
  background: #10b981;
  color: #ffffff;
  box-shadow: 0 2px 8px rgba(16,185,129,0.3);
}

.btn-export-excel:hover {
  background: #059669;
  box-shadow: 0 4px 14px rgba(16,185,129,0.4);
}

/* ─── Footer ─── */
.app-footer {
  display: flex;
  justify-content: flex-end;
  gap: 16px;
  padding-top: 4px;
}

.footer-link {
  font-size: 12px;
  color: #94a3b8;
  text-decoration: none;
  transition: color 0.15s;
}

.footer-link:hover { color: #6366f1; }

/* ─── Modal / Dialog ─── */
.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(15, 23, 42, 0.45);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 999;
  backdrop-filter: blur(2px);
}

.modal-card {
  background: #ffffff;
  border-radius: 16px;
  width: 400px;
  max-width: 92vw;
  padding: 32px;
  box-shadow: 0 20px 60px rgba(15,23,42,0.18), 0 0 0 1px rgba(15,23,42,0.06);
  position: relative;
}

.modal-close {
  position: absolute;
  top: 16px;
  right: 16px;
  width: 28px;
  height: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #f1f5f9;
  border: none;
  border-radius: 6px;
  color: #64748b;
  cursor: pointer;
  font-size: 12px;
  transition: background 0.15s, color 0.15s;
}

.modal-close:hover {
  background: #e2e8f0;
  color: #0f172a;
}

.modal-title {
  font-size: 20px;
  font-weight: 700;
  color: #0f172a;
  letter-spacing: -0.4px;
  margin-bottom: 6px;
}

.modal-subtitle {
  font-size: 13px;
  color: #64748b;
  margin-bottom: 24px;
  line-height: 1.5;
}

.modal-divider {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 20px 0;
}

.modal-divider-line {
  flex: 1;
  height: 1px;
  background: #f1f5f9;
}

.modal-divider-text {
  font-size: 11px;
  color: #94a3b8;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  white-space: nowrap;
}

.modal-terms {
  font-size: 11px;
  color: #94a3b8;
  text-align: center;
  margin-top: 16px;
  line-height: 1.5;
}

/* Logged-in modal */
.modal-logged-in {
  text-align: center;
  padding: 8px 0;
}

.modal-avatar {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: linear-gradient(135deg, #6366f1, #8b5cf6);
  color: #fff;
  font-size: 22px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 12px;
}

.modal-user-name {
  font-size: 15px;
  font-weight: 600;
  color: #0f172a;
}

.modal-user-label {
  font-size: 12px;
  color: #22c55e;
  font-weight: 600;
  margin-top: 4px;
  margin-bottom: 20px;
}

/* Code row */
.code-row {
  display: flex;
  gap: 8px;
}

.btn-code {
  flex-shrink: 0;
  height: 38px;
  padding: 0 14px;
  background: #f8fafc;
  border: 1.5px solid #e2e8f0;
  border-radius: 8px;
  font-size: 12px;
  font-weight: 600;
  color: #6366f1;
  cursor: pointer;
  white-space: nowrap;
  transition: background 0.15s, border-color 0.15s;
  outline: none;
}

.btn-code:hover:not(.btn-code-disabled) {
  background: #f0f0fe;
  border-color: #a5b4fc;
}

.btn-code-disabled {
  color: #94a3b8;
  cursor: not-allowed;
}

/* ─── Comment Section ─── */
.comment-section {
  margin: 20px 32px 0;
}

/* Progress Banner */
.progress-banner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 20px;
  background: #fff8f1;
  border: 1px solid #fed7aa;
  border-radius: 10px 10px 0 0;
  gap: 12px;
  flex-wrap: wrap;
}

.progress-banner-text {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  color: #92400e;
  font-weight: 500;
  flex: 1;
  min-width: 0;
}

.progress-banner-text strong {
  color: #c2410c;
  font-weight: 700;
}

.progress-banner-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
}

.btn-banner-stop {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  height: 30px;
  padding: 0 12px;
  border: 1.5px solid #d1d5db;
  border-radius: 6px;
  background: #ffffff;
  color: #374151;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  outline: none;
  transition: background 0.15s, border-color 0.15s;
}

.btn-banner-stop:hover { background: #f9fafb; border-color: #9ca3af; }

.btn-banner-download {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 30px;
  padding: 0 14px;
  background: #10b981;
  color: #ffffff;
  border: none;
  border-radius: 6px;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  outline: none;
  letter-spacing: 0.2px;
  text-transform: uppercase;
  box-shadow: 0 2px 6px rgba(16,185,129,0.35);
  transition: background 0.15s, box-shadow 0.15s;
}

.btn-banner-download:hover { background: #059669; box-shadow: 0 4px 10px rgba(16,185,129,0.45); }

/* List progress bar (inside status card) */
.list-status-card {
  margin-top: 12px;
  margin-bottom: 12px;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  border-radius: 10px;
  overflow: hidden;

}

/* 灰色为基础轨道，绿色为进度填充，更直观区分 */
.list-progress-wrap {
  position: relative;
  height: 18px;
  background: #e5e7eb;
  border-radius: 999px;
  overflow: hidden;
}



.list-progress-fill {
  height: 100%;
  background: linear-gradient(90deg, #22c55e, #16a34a);
  transition: width 0.4s ease;
  border-radius: inherit;
}

.list-progress-pct {
  position: absolute;
  right: 8px;
  top: 50%;
  transform: translateY(-50%);
  display: flex;
  align-items: center;
  height: 20px;
  font-size: 11px;
  font-weight: 700;
  color: #059669;
  background: #f8fafc;
  padding: 0 4px;
}

/* API Limit Warning */
.availability-notice {
  display: flex;
  gap: 12px;
  padding: 14px 20px;
  background: #fff7ed;
  border: 1.5px solid #fed7aa;
  border-radius: 10px 10px 0 0;
  margin-top: 12px;
}

.availability-notice-icon {
  flex-shrink: 0;
  width: 34px;
  height: 34px;
  border-radius: 50%;
  background: rgba(245, 158, 11, 0.16);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #d97706;
}

.availability-notice-text {
  flex: 1;
  min-width: 0;
}

.availability-notice-text strong {
  display: block;
  font-size: 13px;
  font-weight: 700;
  color: #b45309;
  margin-bottom: 4px;
}

.availability-notice-text p {
  font-size: 12px;
  color: #92400e;
  line-height: 1.5;
  margin: 0;
}

.api-limit-warning {
  display: flex;
  gap: 12px;
  padding: 14px 20px;
  background: linear-gradient(135deg, #fff7ed 0%, #ffedd5 100%);
  border: 1.5px solid #fed7aa;
  border-radius: 10px 10px 0 0;
  margin-top: 12px;
}

.api-limit-icon {
  flex-shrink: 0;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: rgba(251, 146, 60, 0.15);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #ea580c;
}

.api-limit-text {
  flex: 1;
  min-width: 0;
}

.api-limit-text strong {
  display: block;
  font-size: 13px;
  font-weight: 700;
  color: #c2410c;
  margin-bottom: 4px;
}

.api-limit-text p {
  font-size: 12px;
  color: #92400e;
  line-height: 1.5;
  margin: 0;
}

/* Export bar (when finished) */
.list-export-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 20px;
  background: #f0fdf4;
  border-top: 1px solid #bbf7d0;
  border-left: 1px solid #bbf7d0;
  border-right: 1px solid #bbf7d0;
  border-radius: 10px 10px 0 0;
}

/* When API warning is shown, remove top border radius */
.api-limit-warning + .list-export-bar,
.availability-notice + .list-export-bar {
  border-radius: 0;
  border-top: 1px solid #e2e8f0;
}

.list-export-info {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 13px;
  color: #15803d;
  font-weight: 500;
}

.list-export-btns {
  display: flex;
  gap: 8px;
}

.btn-export-sm {
  display: inline-flex;
  align-items: center;
