<template>
  <div class="overlay">
    <div class="dialog-bg"></div>
    <div class="dialog-card">
      <div class="status-icon" :class="isFinishComment ? 'status-verifying' : 'status-pending'">
        <svg v-if="!isFinishComment" width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="#d97706" stroke-width="2">
          <circle cx="12" cy="12" r="10"/>
          <line x1="12" y1="8" x2="12" y2="12"/>
          <line x1="12" y1="16" x2="12.01" y2="16"/>
        </svg>
        <svg v-else class="spin" width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="#6366f1" stroke-width="2">
          <path d="M12 2v4M12 18v4M4.93 4.93l2.83 2.83M16.24 16.24l2.83 2.83M2 12h4M18 12h4M4.93 19.07l2.83-2.83M16.24 7.76l2.83-2.83"/>
        </svg>
      </div>

      <div class="dialog-title">{{ isFinishComment ? 'Verifying your review...' : 'Action Required' }}</div>
      <div class="dialog-body" v-html="content"></div>

      <div v-if="!isFinishComment" class="tip-box">
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#6366f1" stroke-width="2" style="flex-shrink:0;margin-top:1px">
          <circle cx="12" cy="12" r="10"/><line x1="12" y1="16" x2="12" y2="12"/><line x1="12" y1="8" x2="12.01" y2="8"/>
        </svg>
        <span>Keep this window open until your review is complete.</span>
      </div>

      <button
        type="button"
        :class="['btn-primary', isFinishComment ? 'btn-loading' : '']"
        :disabled="isFinishComment"
        @click="handleFinish"
      >
        <svg v-if="isFinishComment" class="spin" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" style="margin-right:6px">
          <path d="M12 2v4M12 18v4M4.93 4.93l2.83 2.83M16.24 16.24l2.83 2.83M2 12h4M18 12h4M4.93 19.07l2.83-2.83M16.24 7.76l2.83-2.83"/>
        </svg>
        {{ isFinishComment ? 'Verifying...' : 'Review Complete — Verify Now' }}
      </button>
    </div>
  </div>
</template>

<script>
import { sendAliLog } from '../../util/alilog'

export default {
  name: 'BonusVerifyDialog',
  data() {
    return {
      isFinishComment: false,
      content: 'Please <strong>do not close</strong> this verification window until your review is fully submitted.'
    }
  },
  methods: {
    async handleFinish() {
      this.isFinishComment = true;
      sendAliLog('2j0142');
      await chrome.storage.local.set({ storageComment: true });
      this.$emit('onClose');
    },
  },
}
</script>

<style scoped>
*, *::before, *::after { box-sizing: border-box; }

.overlay {
  position: fixed;
  inset: 0;
  z-index: 100000;
  display: flex;
  align-items: center;
  justify-content: center;
}

.dialog-bg {
  position: absolute;
  inset: 0;
  background: rgba(15, 23, 42, 0.45);
  backdrop-filter: blur(2px);
}

.dialog-card {
  position: relative;
  z-index: 1;
  background: #ffffff;
  border-radius: 16px;
  padding: 32px 28px 24px;
  width: 380px;
  max-width: 92vw;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  box-shadow: 0 20px 60px rgba(15,23,42,0.2), 0 0 0 1px rgba(15,23,42,0.06);
}

.status-icon {
  width: 60px;
  height: 60px;
  border-radius: 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 16px;
  flex-shrink: 0;
}

.status-pending { background: #fffbeb; }
.status-verifying { background: #f0f0fe; }

.dialog-title {
  font-size: 17px;
  font-weight: 700;
  color: #0f172a;
  letter-spacing: -0.2px;
  margin-bottom: 8px;
}

.dialog-body {
  font-size: 13px;
  color: #64748b;
  line-height: 1.65;
  margin-bottom: 18px;
}

.tip-box {
  display: flex;
  align-items: flex-start;
  gap: 7px;
  background: #f0f0fe;
  border: 1px solid #c7d2fe;
  border-radius: 8px;
  padding: 10px 12px;
  font-size: 12px;
  color: #4f46e5;
  line-height: 1.5;
  margin-bottom: 20px;
  text-align: left;
  width: 100%;
}

.btn-primary {
  width: 100%;
  height: 44px;
  background: #6366f1;
  color: #ffffff;
  border: none;
  border-radius: 10px;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  outline: none;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 2px 8px rgba(99,102,241,0.35);
  transition: background 0.15s, box-shadow 0.15s, transform 0.08s;
}

.btn-primary:hover:not(:disabled) {
  background: #4f46e5;
  box-shadow: 0 4px 14px rgba(99,102,241,0.45);
}

.btn-primary:active:not(:disabled) { transform: scale(0.98); }

.btn-loading {
  background: #818cf8;
  cursor: not-allowed;
  box-shadow: none;
}

@keyframes spin { to { transform: rotate(360deg); } }
.spin { animation: spin 0.9s linear infinite; }
</style>
