/** 缓存处理 **/
/** [缓存]获取Lead数据 **/
export function stgGetLeadList(){
    return new Promise((resolve) => {
        chrome.storage.local.get("lead_list", function(result) {
            let data = result.lead_list ? result.lead_list : []
            resolve(data)
        });
    })
}

/** [缓存]更新Lead数据(全部) **/
export function stgSetLeadList(data){
    return new Promise((resolve) => {
        chrome.storage.local.set({"lead_list": data}, function() {
            resolve(true)
        });
    })
}

/** [缓存]更新Lead数据-单个 **/
export async function stgPushLead(data){
    let lead_list = await stgGetLeadList()
    let result = await stgSetLeadList(lead_list)
    return result
}

/** [缓存]更新Lead数据-批量 **/
export async function stgPushLeadByBatch(userList){
    let lead_list = await stgGetLeadList()
    for(let i=0; i<userList.length; i++){
        lead_list.push(userList[i])
    }
    let bResult = await stgSetLeadList(lead_list)
    return bResult
}

