import { HTTP_ERROR } from "./constants";
import { stgGetAuthToken, stgSetAuthToken, stgClearAuthToken } from "./storage";

const BASE_HOST =
  process.env.NODE_ENV === "development"
    ? "https://devigcomment.igscraper.io"
    : "https://igcomment.igscraper.io";

const API_ROOT = `${BASE_HOST}/extension/user`;
// 固定扩展 id，用于接口校验
const EXTENSION_ID = "hpfnaodfcakdfbnompnfglhjmkoinbfm";

async function request(path, { method = "GET", body, auth = false } = {}) {
  const headers = {
    "Content-Type": "application/json",
    "extension-id": EXTENSION_ID,
  };

  if (auth) {
    const token = await stgGetAuthToken();
    if (token) {
      // 后端期望直接使用 token，无需 Bearer 前缀
      headers["Authorization"] = token;
    }
  }

  const resp = await fetch(`${API_ROOT}${path}`, {
    method,
    headers,
    credentials: "include",
    body: body ? JSON.stringify(body) : undefined,
  });

  let data = {};
  try {
    data = await resp.json();
  } catch (e) {
    // ignore json parse error
  }

  if (!resp.ok || data.stat === HTTP_ERROR) {
    const message =
      (data && (data.message || data.msg)) ||
      `Request failed with status ${resp.status}`;
    throw new Error(message);
  }

  return data;
}

export function getApiBaseHost() {
  return BASE_HOST;
}

export function getGoogleLoginUrl() {
  return `${API_ROOT}/google-login`;
}

function extractToken(data) {
  if (!data) return "";
  // 兼容多种可能字段
  return (
    data.token ||
    data.access_token ||
    (data.data && (data.data.token || data.data.access_token)) ||
    ""
  );
}

export async function clearAuth() {
  await stgClearAuthToken();
}

export async function googleLogin(accessToken) {
  const res = await request("/google-login", {
    method: "POST",
    body: { access_token: accessToken },
  });
  const token = extractToken(res);
  if (token) {
    await stgSetAuthToken(token);
  }
  return res;
}

export async function sendEmailCode(email) {
  // 发送邮箱验证码，返回后端下发的 credential，后续用于 email-login
  return request("/send-code", {
    method: "POST",
    body: { email },
  });
}

export async function emailLogin(email, code, credential) {
  const res = await request("/email-login", {
    method: "POST",
    body: { email, code, credential },
  });
  const token = extractToken(res);
  if (token) {
    await stgSetAuthToken(token);
  }
  return res;
}

export async function fetchUserInfo() {
  // 获取用户信息接口需要携带 Authorization
  return request("/info", { auth: true });
}

export async function createClinkOrder(priceId) {
  // 创建 Clink 订单
  const PAYMENT_API_ROOT = `${BASE_HOST}/extension/payment`;
  const headers = {
    "Content-Type": "application/json",
    "extension-id": EXTENSION_ID,
  };
  
  const token = await stgGetAuthToken();
  if (token) {
    headers["Authorization"] = token;
  }

  const resp = await fetch(`${PAYMENT_API_ROOT}/clink-make-order`, {
    method: "POST",
    headers,
    credentials: "include",
    body: JSON.stringify({ price_id: priceId }),
  });

  let data = {};
  try {
    data = await resp.json();
  } catch (e) {
    // ignore json parse error
  }

  if (!resp.ok || data.code !== 100000) {
    const message =
      (data && (data.message || data.msg)) ||
      `Request failed with status ${resp.status}`;
    throw new Error(message);
  }

  return data;
}

