
export function randomMSec(i) {

    let ms = i+Math.ceil(i*0.1*Math.random())
    console.log("delay ms:",ms)
    return ms

}

export function randomNumber(min, max) {
    return min+Math.ceil((max-min+1)*Math.random())

}

export function formateDate(timestamp) {
    const date = new Date(timestamp);

    const year = date.getFullYear();
    const month = date.getMonth() + 1 < 10 ? `0${date.getMonth() + 1}` : date.getMonth() + 1; // 月份从0开始，所以加1
    const day = date.getDate() < 10 ? `0${date.getDate()}` : date.getDate();
    const hours = date.getHours() < 10 ? `0${date.getHours()}` : date.getHours();
    const minutes =  date.getMinutes() < 10 ? `0${date.getMinutes()}` : date.getMinutes();
    const seconds =  date.getSeconds() < 10 ? `0${date.getSeconds()}` : date.getSeconds();

    // 返回格式化的日期
    return `${year}/${month}/${day} ${hours}:${minutes}:${seconds}`; 
}