<template>
  <transition name="dialog-fade">
    <div v-if="innerVisible" class="modal-overlay" @click.self="handleClose">
      <div class="pricing-card">
        <button type="button" class="modal-close" @click="handleClose">✕</button>

        <div class="pricing-header">
          <div class="pricing-icon">💎</div>
          <div class="pricing-title">Upgrade to Pro</div>
          <div class="pricing-subtitle">Choose the plan that works best for you</div>
        </div>

        <div class="pricing-plans">
          <div 
            v-for="plan in plans" 
            :key="plan.priceId"
            class="plan-card"
            :class="{ 'plan-card-popular': plan.popular }"
          >
            <div v-if="plan.popular" class="plan-badge">Most Popular</div>
            <div class="plan-name">{{ plan.name }}</div>
            <div class="plan-price">
              <span class="plan-price-amount">${{ plan.price }}</span>
              <span class="plan-price-period">{{ plan.period }}</span>
            </div>
            <div v-if="plan.billingNote" class="plan-billing-note">{{ plan.billingNote }}</div>
            <div class="plan-section-title">Value comparison</div>
            <div class="plan-compare" v-if="getPlanCompareStats(plan).length">
              <div
                class="plan-compare-item"
                v-for="(stat, statIdx) in getPlanCompareStats(plan)"
                :key="`${plan.priceId}-${statIdx}`"
              >
                <div class="plan-compare-label">{{ stat.label }}</div>
                <div class="plan-compare-value" :class="{ 'plan-compare-value-accent': stat.accent }">{{ stat.value }}</div>
              </div>
            </div>
            <div class="plan-section-title">What you get</div>
            <ul class="plan-features">
              <li v-for="(feature, idx) in plan.features" :key="idx">
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#10b981" stroke-width="2.5">
                  <polyline points="20 6 9 17 4 12"/>
                </svg>
                <span v-html="formatFeature(feature)"></span>
              </li>
            </ul>
            <button 
              type="button" 
              class="plan-button"
              :class="{ 'plan-button-primary': plan.popular, 'plan-button-loading': loadingPriceId === plan.priceId }"
              :disabled="loadingPriceId !== null"
              @click="handleSelectPlan(plan)"
            >
              <svg v-if="loadingPriceId === plan.priceId" class="spin" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5">
                <path d="M12 2v4M12 18v4M4.93 4.93l2.83 2.83M16.24 16.24l2.83 2.83M2 12h4M18 12h4M4.93 19.07l2.83-2.83M16.24 7.76l2.83-2.83"/>
              </svg>
              <span v-if="loadingPriceId === plan.priceId">Processing...</span>
              <span v-else>{{ plan.buttonText }}</span>
            </button>
          </div>
        </div>

        <div class="pricing-footer">
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#94a3b8" stroke-width="2">
            <rect x="3" y="11" width="18" height="11" rx="2" ry="2"/>
            <path d="M7 11V7a5 5 0 0 1 10 0v4"/>
          </svg>
          <span>Secure payment powered by Clink</span>
        </div>
      </div>
    </div>
  </transition>
</template>

<script>
import { createClinkOrder } from "@/common/userApi";

// 根据构建环境区分测试 / 正式环境的 priceId
const IS_DEV = process.env.NODE_ENV === "development";

// 测试环境（dev）使用你提供的测试 priceId，
// 正式环境请在这里替换为真实线上 priceId。
const PRICE_IDS = IS_DEV
  ? {
      monthly: "price_ffulx71n0jrl",
      yearly: "price_ffum2anjbpil",
      lifetime: "price_ffum5vsvbywj",
    }
  : {
      monthly: "price_ffv745ep5h2p",
      yearly: "price_ffv76qaz7jy1",
      lifetime: "price_ffv79535pr5i",
    };

export default {
  name: "PricingDialog",
  props: {
    visible: {
      type: Boolean,
      default: false,
    },
  },
  data() {
    return {
      innerVisible: this.visible,
      loadingPriceId: null,
      plans: [
        {
          name: "Monthly",
          priceId: PRICE_IDS.monthly,
          price: "12.95",
          period: "/month",
          buttonText: "Start Monthly",
          popular: false,
          features: [
            "Unlimited exports",
            "Priority support",
            "No ads",
            "Cancel anytime",
          ],
        },
        {
          name: "Yearly",
          priceId: PRICE_IDS.yearly,
          price: "7.50",
          period: "/month",
          billingNote: "$89.95/year billed yearly",
          buttonText: "Get Yearly",
          popular: true,
          features: [
            "Unlimited exports",
            "Priority support",
            "No ads",
            "Save 42% vs monthly",
          ],
        },
        {
          name: "Lifetime",
          priceId: PRICE_IDS.lifetime,
          price: "129",
          period: "one-time",
          buttonText: "Get Lifetime Access",
          popular: false,
          features: [
            "Unlimited exports forever",
            "Priority support",
            "No ads",
            "All future updates",
          ],
        },
      ],
    };
  },
  watch: {
    visible(val) {
      this.innerVisible = val;
    },
    innerVisible(val) {
      this.$emit("update:visible", val);
    },
  },
  methods: {
    getPlanCompareStats(plan) {
      const monthlyPrice = 12.95;
      const yearlyPrice = 89.95;
      const yearlyMonthlyPrice = yearlyPrice / 12;
      const yearlyDailyPrice = yearlyPrice / 365;
      const yearlySavings = monthlyPrice * 12 - yearlyPrice;
      const yearlyDiscountPercent = Math.round((yearlySavings / (monthlyPrice * 12)) * 100);

      if (plan.name === "Monthly") {
        return [
          { label: "Daily cost", value: `$${(monthlyPrice / 30).toFixed(2)}/day`, accent: false },
          { label: "Yearly total", value: `$${(monthlyPrice * 12).toFixed(2)}`, accent: false },
        ];
      }

      if (plan.name === "Yearly") {
        return [
          { label: "You save / year", value: `$${yearlySavings.toFixed(2)}`, accent: true },
          { label: "Discount", value: `${yearlyDiscountPercent}% OFF`, accent: true },
          { label: "Effective daily", value: `$${yearlyDailyPrice.toFixed(2)}/day`, accent: false },
          { label: "Effective monthly", value: `$${yearlyMonthlyPrice.toFixed(2)}/mo`, accent: false },
        ];
      }

      if (plan.name === "Lifetime") {
        const monthsToBreakEven = Math.ceil(129 / monthlyPrice);
        return [
          { label: "Break-even", value: `${monthsToBreakEven} months`, accent: true },
          { label: "vs Monthly 2 years", value: `$${(monthlyPrice * 24 - 129).toFixed(2)} saved`, accent: false },
        ];
      }

      return [];
    },
    formatFeature(feature) {
      if (feature === "Save 42% vs monthly") {
        return 'Save <span class="feature-highlight-number">42%</span> vs monthly';
      }
      return feature;
    },
    handleClose() {
      if (this.loadingPriceId) return;
      this.innerVisible = false;
    },
    async handleSelectPlan(plan) {
      if (this.loadingPriceId) return;
      
      this.loadingPriceId = plan.priceId;
      try {
        const res = await createClinkOrder(plan.priceId);
        if (res && res.code === 100000 && res.data && res.data.url) {
          window.open(res.data.url, "_blank");
          this.$message.success("Redirecting to payment page...");
        } else {
          this.$message.error("Failed to create order, please try again");
        }
      } catch (e) {
        this.$message.error(e.message || "Failed to create order");
      } finally {
        this.loadingPriceId = null;
      }
    },
  },
};
</script>

<style scoped>
*, *::before, *::after { box-sizing: border-box; }

.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(15, 23, 42, 0.45);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 9999;
  backdrop-filter: blur(3px);
}

.pricing-card {
  background: #ffffff;
  border-radius: 20px;
  width: 760px;
  max-width: 95vw;
  max-height: none;
  overflow: visible;
  padding: 28px 24px 20px;
  position: relative;
  box-shadow: 0 20px 60px rgba(15,23,42,0.2), 0 0 0 1px rgba(15,23,42,0.06);
}

.modal-close {
  position: absolute;
  top: 16px;
  right: 16px;
  width: 32px;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #f1f5f9;
  border: none;
  border-radius: 8px;
  color: #64748b;
  font-size: 14px;
  cursor: pointer;
  transition: background 0.15s, color 0.15s;
  z-index: 10;
}

.modal-close:hover { background: #e2e8f0; color: #0f172a; }

.pricing-header {
  text-align: center;
  margin-bottom: 18px;
}

.pricing-icon {
  font-size: 36px;
  line-height: 1;
  margin-bottom: 10px;
}

.pricing-title {
  font-size: 24px;
  font-weight: 800;
  color: #0f172a;
  letter-spacing: -0.6px;
  margin-bottom: 6px;
}

.pricing-subtitle {
  font-size: 13px;
  color: #64748b;
  line-height: 1.5;
}

.pricing-plans {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 14px;
  margin-bottom: 14px;
  align-items: stretch;
}

.plan-card {
  background: #ffffff;
  border: 2px solid #e2e8f0;
  border-radius: 16px;
  padding: 16px 14px 14px;
  position: relative;
  transition: transform 0.2s, box-shadow 0.2s, border-color 0.2s;
  display: flex;
  flex-direction: column;
  min-height: 100%;
}

.plan-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 12px 32px rgba(15,23,42,0.12);
  border-color: #cbd5e1;
}

.plan-card-popular {
  border-color: #6366f1;
  border-width: 2.5px;
  box-shadow: 0 10px 28px rgba(99,102,241,0.2);
  padding-top: 24px;
  margin-top: 8px;
  background: linear-gradient(180deg, #ffffff 0%, #fbfaff 100%);
}

.plan-card-popular:hover {
  border-color: #4f46e5;
  box-shadow: 0 12px 36px rgba(99,102,241,0.25);
}

.plan-badge {
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: linear-gradient(135deg, #6366f1, #8b5cf6);
  color: #ffffff;
  padding: 5px 18px;
  border-radius: 99px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.8px;
  text-transform: uppercase;
  box-shadow: 0 4px 14px rgba(99,102,241,0.4);
  white-space: nowrap;
}

.plan-name {
  font-size: 17px;
  font-weight: 700;
  color: #0f172a;
  margin-bottom: 8px;
  text-align: center;
  margin-top: 4px;
}

.plan-price {
  text-align: center;
  margin-bottom: 6px;
}

.plan-price-amount {
  font-size: 32px;
  font-weight: 800;
  color: #0f172a;
  letter-spacing: -1px;
}

.plan-price-period {
  font-size: 14px;
  color: #64748b;
  font-weight: 500;
  margin-left: 4px;
}

.plan-billing-note {
  text-align: center;
  font-size: 11px;
  color: #64748b;
  margin-bottom: 6px;
}

.plan-section-title {
  font-size: 10px;
  font-weight: 700;
  color: #64748b;
  letter-spacing: 0.4px;
  text-transform: uppercase;
  margin: 8px 0 6px;
}

.plan-compare {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin: 0 0 8px;
}

.plan-compare-item {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  padding: 2px 0;
  border-bottom: 1px solid #eef2f7;
}

.plan-card-popular .plan-compare-item {
  border-bottom-color: #dbe4ff;
}

.plan-card-popular .plan-compare-value {
  font-size: 15px;
}

.plan-card-popular .plan-compare-value-accent {
  color: #6d28d9;
}

.plan-compare-label {
  font-size: 11px;
  color: #64748b;
  line-height: 1.35;
}

.plan-compare-value {
  font-size: 13px;
  font-weight: 800;
  color: #0f172a;
  line-height: 1.2;
  white-space: nowrap;
}

.plan-compare-value-accent {
  color: #7c3aed;
}

.plan-features {
  list-style: none;
  padding: 0;
  margin: 0 0 12px;
  flex: 1;
  border-top: 1px dashed #e2e8f0;
  padding-top: 8px;
}

.plan-features li {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  font-size: 12px;
  color: #334155;
  margin-bottom: 6px;
  line-height: 1.5;
}

.plan-features li:last-child {
  margin-bottom: 0;
}

.plan-features :deep(.feature-highlight-number) {
  display: inline-block;
  font-size: 18px;
  line-height: 1;
  font-weight: 900;
  color: #7c3aed;
  margin: 0 2px;
  text-shadow: 0 2px 8px rgba(124, 58, 237, 0.25);
}

.plan-features svg {
  flex-shrink: 0;
  margin-top: 2px;
}

.plan-button {
  width: 100%;
  height: 40px;
  border-radius: 10px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  border: none;
  outline: none;
  transition: background 0.15s, box-shadow 0.15s, opacity 0.15s, transform 0.08s;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  background: #f8fafc;
  color: #334155;
  border: 2px solid #e2e8f0;
}

@media (max-width: 900px) {
  .pricing-plans {
    grid-template-columns: 1fr;
  }
}

.plan-button:hover:not(:disabled) {
  background: #f1f5f9;
  border-color: #cbd5e1;
}

.plan-button:active:not(:disabled) {
  transform: scale(0.98);
}

.plan-button:disabled {
  cursor: not-allowed;
  opacity: 0.6;
}

.plan-button-primary {
  background: linear-gradient(135deg, #6366f1, #8b5cf6);
  color: #ffffff;
  border: none;
  box-shadow: 0 4px 14px rgba(99,102,241,0.35);
}

.plan-button-primary:hover:not(:disabled) {
  background: linear-gradient(135deg, #4f46e5, #7c3aed);
  box-shadow: 0 6px 20px rgba(99,102,241,0.45);
}

.plan-button-loading {
  background: #e0e7ff !important;
  color: #6366f1 !important;
  border-color: #c7d2fe !important;
}

.pricing-footer {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding-top: 12px;
  font-size: 11px;
  color: #94a3b8;
  border-top: 1px solid #f1f5f9;
}

.pricing-footer svg {
  flex-shrink: 0;
}

@keyframes spin { to { transform: rotate(360deg); } }
.spin { animation: spin 0.9s linear infinite; }

.dialog-fade-enter-active, .dialog-fade-leave-active {
  transition: opacity 0.25s;
}
.dialog-fade-enter-active .pricing-card,
.dialog-fade-leave-active .pricing-card {
  transition: transform 0.25s, opacity 0.25s;
}
.dialog-fade-enter, .dialog-fade-leave-to { opacity: 0; }
.dialog-fade-enter .pricing-card, .dialog-fade-leave-to .pricing-card {
  transform: scale(0.94) translateY(12px);
  opacity: 0;
}
</style>
