<template>
  <transition name="dialog-fade">
    <div v-if="innerVisible" class="modal-overlay" @click.self="handleClose">
      <div class="modal-card">
        <button type="button" class="modal-close" @click="handleClose">✕</button>

        <!-- Logged In State -->
        <div v-if="isLoggedIn" class="state-logged-in">
          <div class="avatar">{{ displayName.charAt(0).toUpperCase() }}</div>
          <div class="user-name">{{ displayName }}</div>
          <div class="user-tag">Signed in</div>
          <p class="logged-hint">You are signed in. Enjoy enhanced export features.</p>
        </div>

        <!-- Login Form -->
        <div v-else class="state-login">
          <div class="modal-brand">
            <div class="modal-icon">IG</div>
          </div>
          <div class="modal-title">Sign in to IG Tools</div>
          <div class="modal-subtitle">Unlock higher limits and sync your export settings.</div>

          <button
            class="btn-google"
            :class="{ loading: googleLoading }"
            :disabled="googleLoading"
            @click="handleGoogleLogin"
          >
            <svg v-if="!googleLoading" width="18" height="18" viewBox="0 0 24 24" style="flex-shrink:0">
              <path fill="#4285F4" d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"/>
              <path fill="#34A853" d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"/>
              <path fill="#FBBC05" d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l3.66-2.84z"/>
              <path fill="#EA4335" d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z"/>
            </svg>
            <svg v-else class="spin" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" style="flex-shrink:0">
              <path d="M12 2v4M12 18v4M4.93 4.93l2.83 2.83M16.24 16.24l2.83 2.83M2 12h4M18 12h4M4.93 19.07l2.83-2.83M16.24 7.76l2.83-2.83"/>
            </svg>
            <span>{{ googleLoading ? 'Connecting...' : 'Continue with Google' }}</span>
          </button>

          <div class="divider">
            <span class="divider-line"></span>
            <span class="divider-text">or email</span>
            <span class="divider-line"></span>
          </div>

          <div class="field">
            <label class="field-label">Email</label>
            <input
              class="field-input"
              type="email"
              v-model="form.email"
              placeholder="you@example.com"
              autocomplete="off"
            />
          </div>

          <div class="field">
            <label class="field-label">Verification Code</label>
            <div class="code-row">
              <input
                class="field-input"
                type="text"
                v-model="form.code"
                placeholder="6-digit code"
                autocomplete="off"
              />
              <button
                type="button"
                class="btn-send-code"
                :class="{ disabled: sendingCode || !form.email || countdown > 0 }"
                :disabled="sendingCode || !form.email || countdown > 0"
                @click="onSendCode"
              >
                <span v-if="countdown > 0">{{ countdown }}s</span>
                <span v-else-if="sendingCode">Sending</span>
                <span v-else>Send code</span>
              </button>
            </div>
          </div>

          <button
            type="button"
            class="btn-submit"
            :class="{ disabled: emailLoading || !form.email || !form.code }"
            :disabled="emailLoading || !form.email || !form.code"
            @click="onEmailLogin"
          >
            <span v-if="emailLoading">Signing in...</span>
            <span v-else>Sign in</span>
          </button>

          <div class="terms">
            By continuing, you agree to our
            <a href="https://igcomment.igscraper.io/terms" target="_blank">Terms</a>
            and
            <a href="https://devigcomment.igscraper.io/privacy" target="_blank">Privacy Policy</a>.
          </div>
        </div>
      </div>
    </div>
  </transition>
</template>

<script>
import {
  googleLogin as apiGoogleLogin,
  sendEmailCode,
  emailLogin,
  fetchUserInfo,
} from "@/common/userApi";

export default {
  name: "UserLoginDialog",
  props: {
    visible: {
      type: Boolean,
      default: false,
    },
    userInfo: {
      type: Object,
      default: () => null,
    },
  },
  data() {
    return {
      innerVisible: this.visible,
      form: { email: "", code: "" },
      credential: "",
      sendingCode: false,
      countdown: 0,
      countdownTimer: null,
      emailLoading: false,
      googleLoading: false,
    };
  },
  computed: {
    isLoggedIn() {
      return !!this.userInfo;
    },
    displayName() {
      if (!this.userInfo) return "";
      return this.userInfo.email || this.userInfo.username || this.userInfo.name || "";
    },
  },
  watch: {
    visible(val) {
      this.innerVisible = val;
    },
    innerVisible(val) {
      this.$emit("update:visible", val);
    },
  },
  methods: {
    handleClose() {
      this.clearCountdown();
      this.innerVisible = false;
    },
    startCountdown() {
      this.countdown = 60;
      this.clearCountdown();
      this.countdownTimer = setInterval(() => {
        if (this.countdown <= 1) {
          this.clearCountdown();
          this.countdown = 0;
        } else {
          this.countdown -= 1;
        }
      }, 1000);
    },
    clearCountdown() {
      if (this.countdownTimer) {
        clearInterval(this.countdownTimer);
        this.countdownTimer = null;
      }
    },
    async onSendCode() {
      const email = (this.form.email || "").trim();
      if (!email) { this.$message.error("Please enter your email"); return; }
      this.sendingCode = true;
      try {
        const res = await sendEmailCode(email);
        const credential =
          (res && res.data && res.data.credential) ||
          (res && res.credential) ||
          "";
        if (!credential) {
          this.$message.error("Failed to get verification credential, please try again");
          return;
        }
        this.credential = credential;
        this.$message.success("Code sent! Check your inbox.");
        this.startCountdown();
      } catch (e) {
        this.$message.error(e.message || "Failed to send code");
      } finally {
        this.sendingCode = false;
      }
    },
    async onEmailLogin() {
      const email = (this.form.email || "").trim();
      const code = (this.form.code || "").trim();
      if (!email || !code) { this.$message.error("Please enter email and verification code"); return; }
      if (!this.credential) { this.$message.error("Please get the verification code first"); return; }
      this.emailLoading = true;
      try {
        await emailLogin(email, code, this.credential);
        // 登录成功后，使用 token 再请求 /extension/user/info，拿到完整用户信息
        const infoRes = await fetchUserInfo();
        const raw = infoRes && infoRes.data ? infoRes.data : infoRes;
        const user = (raw && raw.user_info) || raw || { email };
        const payInfo = (raw && raw.pay_info) || [];
        this.$emit("logged-in", { user, pay_info: payInfo });
        this.$message.success("Login successful");
        this.innerVisible = false;
      } catch (e) {
        this.$message.error(e.message || "Login failed");
      } finally {
        this.emailLoading = false;
      }
    },
    async handleGoogleLogin() {
      this.googleLoading = true;
      try {
        const params = new URLSearchParams({
          client_id: "821164619990-orsv51pou1iappumh5dkji7kjs31gthi.apps.googleusercontent.com",
          response_type: "token",
          redirect_uri: chrome.identity.getRedirectURL(),
          scope: "openid email",
        });
        const authUrl = `https://accounts.google.com/o/oauth2/v2/auth?${params.toString()}`;
        const _this = this;
        chrome.identity.launchWebAuthFlow({ url: authUrl, interactive: true }, async function (responseUrl) {
          if (chrome.runtime.lastError || !responseUrl || !responseUrl.includes("access_token")) {
            _this.googleLoading = false;
            _this.$message.error("Google authorization failed, please try again");
            return;
          }
          const fragmentParams = new URLSearchParams(responseUrl.split("#")[1] || "");
          const accessToken = fragmentParams.get("access_token");
          if (!accessToken) {
            _this.googleLoading = false;
            _this.$message.error("Google authorization failed, please try again");
            return;
          }
          await _this.googleLogin(accessToken);
        });
      } catch (error) {
        this.$message.error("Google login failed, please try again");
        this.googleLoading = false;
      }
    },
    async googleLogin(access_token) {
      try {
        const response = await apiGoogleLogin(access_token);
        if (response && response.code === 100000 && response.data && response.data.token) {
          // 谷歌登录成功后，再请求 /extension/user/info，保证与后台状态同步
          const infoRes = await fetchUserInfo();
          const raw = infoRes && infoRes.data ? infoRes.data : infoRes;
          const user = (raw && raw.user_info) || raw || { email: response.data.email };
          const payInfo = (raw && raw.pay_info) || [];
          this.$emit("logged-in", { user, pay_info: payInfo });
          this.$message.success("Login successful");
          this.innerVisible = false;
        } else {
          this.$message.error("Google login failed, please try again");
        }
      } catch (error) {
        this.$message.error("Google login failed, please try again");
      } finally {
        this.googleLoading = false;
      }
    },
  },
  beforeDestroy() {
    this.clearCountdown();
  },
};
</script>

<style scoped>
*, *::before, *::after { box-sizing: border-box; }

.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(15, 23, 42, 0.45);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 9999;
  backdrop-filter: blur(3px);
}

.modal-card {
  background: #ffffff;
  border-radius: 16px;
  width: 400px;
  max-width: 92vw;
  padding: 32px;
  position: relative;
  box-shadow: 0 20px 60px rgba(15,23,42,0.18), 0 0 0 1px rgba(15,23,42,0.06);
}

.modal-close {
  position: absolute;
  top: 14px;
  right: 14px;
  width: 28px;
  height: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #f1f5f9;
  border: none;
  border-radius: 6px;
  color: #64748b;
  font-size: 12px;
  cursor: pointer;
  transition: background 0.15s, color 0.15s;
}

.modal-close:hover { background: #e2e8f0; color: #0f172a; }

/* Brand */
.modal-brand {
  display: flex;
  justify-content: center;
  margin-bottom: 16px;
}

.modal-icon {
  width: 44px;
  height: 44px;
  border-radius: 12px;
  background: linear-gradient(135deg, #6366f1, #8b5cf6);
  color: #fff;
  font-size: 14px;
  font-weight: 800;
  display: flex;
  align-items: center;
  justify-content: center;
  letter-spacing: -0.5px;
}

.modal-title {
  font-size: 20px;
  font-weight: 700;
  color: #0f172a;
  text-align: center;
  letter-spacing: -0.4px;
  margin-bottom: 6px;
}

.modal-subtitle {
  font-size: 13px;
  color: #64748b;
  text-align: center;
  margin-bottom: 24px;
  line-height: 1.5;
}

/* Google Button */
.btn-google {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  width: 100%;
  height: 44px;
  background: #ffffff;
  border: 1.5px solid #e2e8f0;
  border-radius: 10px;
  font-size: 14px;
  font-weight: 600;
  color: #334155;
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s, box-shadow 0.15s;
  outline: none;
}

.btn-google:hover:not(:disabled) {
  background: #f8fafc;
  border-color: #cbd5e1;
  box-shadow: 0 2px 8px rgba(15,23,42,0.08);
}

.btn-google:disabled { opacity: 0.65; cursor: not-allowed; }
.btn-google.loading { background: #f8fafc; }

/* Divider */
.divider {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 20px 0;
}

.divider-line {
  flex: 1;
  height: 1px;
  background: #f1f5f9;
}

.divider-text {
  font-size: 11px;
  color: #94a3b8;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  white-space: nowrap;
}

/* Fields */
.field {
  margin-bottom: 14px;
}

.field-label {
  display: block;
  font-size: 12px;
  font-weight: 600;
  color: #475569;
  margin-bottom: 5px;
  letter-spacing: 0.1px;
}

.field-input {
  width: 100%;
  height: 40px;
  padding: 0 12px;
  border: 1.5px solid #e2e8f0;
  border-radius: 8px;
  font-size: 13px;
  color: #0f172a;
  background: #f8fafc;
  outline: none;
  transition: border-color 0.15s, box-shadow 0.15s, background 0.15s;
}

.field-input:hover { background: #fff; border-color: #cbd5e1; }
.field-input:focus {
  background: #fff;
  border-color: #6366f1;
  box-shadow: 0 0 0 3px rgba(99,102,241,0.12);
}

/* Code row */
.code-row { display: flex; gap: 8px; }

.btn-send-code {
  flex-shrink: 0;
  height: 40px;
  padding: 0 14px;
  background: #f0f0fe;
  border: 1.5px solid #a5b4fc;
  border-radius: 8px;
  font-size: 12px;
  font-weight: 600;
  color: #6366f1;
  cursor: pointer;
  white-space: nowrap;
  outline: none;
  transition: background 0.15s, border-color 0.15s;
}

.btn-send-code:hover:not(.disabled) { background: #e0e7ff; border-color: #818cf8; }
.btn-send-code.disabled { background: #f8fafc; border-color: #e2e8f0; color: #94a3b8; cursor: not-allowed; }

/* Submit */
.btn-submit {
  width: 100%;
  height: 44px;
  background: #6366f1;
  color: #ffffff;
  border: none;
  border-radius: 10px;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  outline: none;
  margin-top: 4px;
  box-shadow: 0 2px 8px rgba(99,102,241,0.35);
  transition: background 0.15s, box-shadow 0.15s, transform 0.08s;
}

.btn-submit:hover:not(.disabled) {
  background: #4f46e5;
  box-shadow: 0 4px 14px rgba(99,102,241,0.45);
}

.btn-submit:active:not(.disabled) { transform: scale(0.98); }
.btn-submit.disabled { background: #c7d2fe; cursor: not-allowed; box-shadow: none; }

/* Terms */
.terms {
  font-size: 11px;
  color: #94a3b8;
  text-align: center;
  margin-top: 14px;
  line-height: 1.5;
}

.terms a { color: #6366f1; text-decoration: none; }
.terms a:hover { text-decoration: underline; }

/* Logged in state */
.state-logged-in {
  text-align: center;
  padding: 16px 0 8px;
}

.avatar {
  width: 60px;
  height: 60px;
  border-radius: 50%;
  background: linear-gradient(135deg, #6366f1, #8b5cf6);
  color: #fff;
  font-size: 24px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 12px;
  box-shadow: 0 4px 14px rgba(99,102,241,0.4);
}

.user-name {
  font-size: 16px;
  font-weight: 700;
  color: #0f172a;
}

.user-tag {
  display: inline-block;
  margin-top: 4px;
  padding: 2px 10px;
  background: #f0fdf4;
  color: #16a34a;
  border-radius: 99px;
  font-size: 11px;
  font-weight: 600;
}

.logged-hint {
  font-size: 13px;
  color: #64748b;
  margin-top: 12px;
}

/* Spin animation */
@keyframes spin { to { transform: rotate(360deg); } }
.spin { animation: spin 0.9s linear infinite; }

/* Fade transition */
.dialog-fade-enter-active, .dialog-fade-leave-active {
  transition: opacity 0.2s;
}
.dialog-fade-enter-active .modal-card,
.dialog-fade-leave-active .modal-card {
  transition: transform 0.2s, opacity 0.2s;
}
.dialog-fade-enter, .dialog-fade-leave-to { opacity: 0; }
.dialog-fade-enter .modal-card, .dialog-fade-leave-to .modal-card {
  transform: scale(0.96) translateY(8px);
  opacity: 0;
}
</style>
