import { sendAliLog } from "../util/alilog";
import {HTTP_ERROR,HTTP_OK, LIMIT_ERROR} from "./constants";
import { stgGetParsingSetting } from "./storage";

function errorWrapper({code, message, type = '' }) {
    let errorRes = {
        stat: HTTP_ERROR,
        code,
        message,
        type,
    }
    return JSON.stringify(errorRes)
}


function handleFetchResponse(response) {
    // 测试不同状态码
    // let response = {
    //     status: 500
    // }
    if (response.status === 200 || (response.status >= 300 && response.status < 400) ) {
        // 200 请求成功，直接返回响应
        // 301 重定向, 也是直接返回响应
        return response
    } else if (response.status >= 400 && response.status < 500) {
        // 4XX 错误
        if (response.status === 404) {
            throw new Error(errorWrapper({
                code: response.status,
                message: "404 Instagram post url not found",
            })); 
        } else {
            throw new Error(errorWrapper({
                code: response.status,
                message: "Please wait a few minutes before you try again",
                type: LIMIT_ERROR
            }));
        }
    } else if (response.status >= 500 && response.status < 600) {
        // 5XX
        throw new Error(errorWrapper({
            code: response.status,
            message: "Instagram Web Server Error",
        }));
    } else {
        // 其他状态码处理
        throw new Error(errorWrapper({
            code: response.status,
            message: "Fetch Error",
        }));
    }
}

function fetchWithTimeout(url, options, timeout = 10000) {
    return Promise.race([
        fetch(url, options),
        new Promise((_, reject) =>
            setTimeout(() => reject(new Error(JSON.stringify({
                code: 1000,
                message: 'Network Timeout'
            }))), timeout)
        ),
    ]);
}

export function fetchPage(post_url) {
    let result = {
        stat: HTTP_ERROR,
        data:{}
    }
    return new Promise(async(resolve, reject) => {
        fetchWithTimeout(post_url, { credentials: 'include' }).then(handleFetchResponse).then(async resp => {
            const data =await resp.json();
            const jsonDataStr = JSON.stringify(data);
            const pSetting = await stgGetParsingSetting();
            setTimeout(async ()=>{
                if (resp.status === 200) {
                    sendAliLog('2j0080',{
                        ...pSetting,
                        http_code: resp.status,
                        http_url: post_url,
                        http_response: jsonDataStr,
                        http_status: data?.status
                    });
                }
                // 导出完成
                if(data?.data?.shortcode_media?.edge_media_to_comment?.page_info?.has_next_page===false){
                    sendAliLog('2j0090',{
                        ...pSetting,
                        parsing_state: 3,
                        http_code: resp.status,
                        http_url: post_url,
                        http_response: jsonDataStr,
                        http_status: data?.status
                    });
                }
            },200)
            
            return data;
        }).then(data => {
            result.stat = HTTP_OK
            result.data = data
            resolve(result)
        }).catch( err => {
            // reject(result)
            setTimeout(async () => {
                const pSetting = await stgGetParsingSetting();
                const errMsg = JSON.parse(err.message)
                sendAliLog('2j0082',{
                    ...pSetting,
                    http_code: Number(errMsg.code),
                    http_url: post_url,
                    http_response: {message: errMsg.message},
                    http_status: 'fail'
                });
            }, 200)
            reject(err)
        })
    })
}

export function fetchJson(post_url) {
    let result = {
        stat: HTTP_ERROR,
        data: {}
    }
    return new Promise((resolve, reject) => {
        fetchWithTimeout(post_url, {
            credentials: 'include',
            headers: {
                'X-ASBD-ID': '129477',
                'X-IG-App-ID': '936619743392459',
                'X-Requested-With': 'XMLHttpRequest'
            }
        }).then(handleFetchResponse).then(async resp => {
            const data = await resp.json();
            result.stat = HTTP_OK
            result.data = data
            resolve(result)
        }).catch(err => {
            reject(err)
        })
    })
}
